(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c9"]=[{"id":"00011720","register_sub_id":"101","register_pk":"210736","name":"愛知県立安城農林高等学校正門門柱（旧愛知県立農林学校正門）","kana":"あいちけんりつあんじょうのうりんこうとうがっこうせいもんもんちゅう（きゅうあいちけんりつのうりんがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市池浦町茶筅木1","lat":34.967708,"lng":137.079169,"geo_status":"db","era":"明治36年頃／昭和5年頃改修、昭和35年移設","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造、間口8.3m、西方脇柱付","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0490","desc":"敷地南面に建つ。石造の主柱と鉄筋コンクリート造モルタル仕上げの左脇柱一本からなる。柱頭部は丁寧に繰型を施しており、柱頂部にはかつて擬宝珠状の装飾があった。左脇柱は当初は木製であった。県内における最古の学校門柱として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011720"},{"id":"00011713","register_sub_id":"101","register_pk":"210729","name":"愛知県立惟信高等学校正門門柱（旧愛知県惟信中学校正門）","kana":"あいちけんりついしんこうとうがっこうせいもんもんちゅう（きゅうあいちけんいしんちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市港区惟信町2-262","lat":35.106781,"lng":136.841848,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0483","desc":"敷地北面に建つ。主柱と脇柱各二本からなる。鉄筋コンクリート造モルタル仕上げで、外観はセセッション風に直線で構成され、柱身部は目地を切り、柱頭部は幾何学模様で装飾する。門扉を除き保存状態も良く、愛知県営繕課による標準設計の門を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011713"},{"id":"00011715","register_sub_id":"101","register_pk":"210731","name":"愛知県立岩津高等学校正門旧門柱（旧岩津町立愛知県岩津農商学校正門）","kana":"あいちけんりついわづこうとうがっこうせいもんきゅうもんちゅう（きゅういわづちょうりつあいちけんいわづのうしょうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県岡崎市東蔵前町字馬場5","lat":34.999063,"lng":137.174453,"geo_status":"db","era":"昭和12年／昭和60年移設","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、間口9.1m","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0485","desc":"敷地南面に建つ。花崗岩製の主柱二本からなる。主柱は角柱で、柱身部は江戸切こぶ出し仕上げで、笠石を載せ、柱頂部に直径五四センチメートルの半球で飾る特徴的な意匠を持つ。移設されているが、地中に柱礎部も残り、当初の意匠をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011715"},{"id":"00011714","register_sub_id":"101","register_pk":"210730","name":"愛知県立岡崎高等学校正門門柱（旧愛知県立第二中学校正門）","kana":"あいちけんりつおかざきこうとうがっこうせいもんもんちゅう（きゅうあいちけんりつだいにちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市明大寺町伝馬1","lat":34.946312,"lng":137.169859,"geo_status":"db","era":"大正前期／大正13年・昭和47年移設","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、間口8.6m、南北脇柱付","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0484","desc":"敷地西側に建つ。花崗岩製の主柱と脇柱各二本からなる。西洋建築のオーダーを基調とした意匠で柱礎部、柱身部、柱頭部からなる。柱身部は江戸切こぶ出し仕上げで、柱頭部は繰型を施し大きく張り出す。県内旧制中学校正門の古例で西洋趣味の強い意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011714"},{"id":"00011721","register_sub_id":"101","register_pk":"210737","name":"愛知県立鶴城丘高等学校正門門柱（旧愛知県蚕糸学校正門）","kana":"あいちけんりつかくじょうがおかこうとうがっこうせいもんもんちゅう（きゅうあいちけんさんしがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県西尾市亀沢町300","lat":34.87253,"lng":137.048567,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0491","desc":"愛知県蚕糸学校の正門として建てられた。鉄筋コンクリート造モルタル仕上げで目地を刻み石造風に三層構成とする県立高校の標準設計に基づく意匠とし、主柱の高さは三・六メートル。脇柱は主柱の九割程度の大きさ。セセッション風意匠で、地域の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011721"},{"id":"00011719","register_sub_id":"101","register_pk":"210735","name":"愛知県立刈谷高等学校正門門柱（旧愛知県刈谷中学校正門）","kana":"あいちけんりつかりやこうとうがっこうせいもんもんちゅう（きゅうあいちけんかりやちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県刈谷市寿町五丁目101","lat":34.983017,"lng":136.998324,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0489","desc":"敷地南面に建つ。主柱と脇柱各二本からなる鉄筋コンクリート造モルタル仕上げの門である。外観はセセッション風に直線で構成され、柱頭部には幾何学模様の装飾を付す。柱身部は石造風に目地を切る。愛知県営繕課の当時の標準設計の門で、門扉を除き残りも良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011719"},{"id":"00011724","register_sub_id":"101","register_pk":"210740","name":"愛知県立小牧高等学校正門門柱（旧愛知県小牧中学校正門）","kana":"あいちけんりつこまきこうとうがっこうせいもんもんちゅう（きゅうあいちけんこまきちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県小牧市小牧一丁目321","lat":35.291777,"lng":136.918696,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、間口9.1m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0494","desc":"鉄筋コンクリート造で、ほぼ正方形の平面、石造風の外観、三層構成など、標準的な構成をとる。主柱高さは三・〇メートルで、脇柱はその九割程度の規模を有する。柱頭部にアカンサスの葉を模した装飾を備える点が特徴で、学校の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011724"},{"id":"00014243","register_sub_id":"101","register_pk":"509633","name":"愛知県立瑞陵高等学校感喜堂（旧講堂）","kana":"あいちけんりつずいりょうこうとうがっこうかんきどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市瑞穂区北原町二丁目1-2","lat":35.13234444,"lng":136.92979722,"geo_status":"db","era":"大正13年／昭和54年・平成27年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積427㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"23 - 0577","desc":"校地南西隅に建つ鉄筋コンクリート造の旧講堂。寄棟造桟瓦葺で四面に切妻破風を立ち上げ、縦長のガラス窓が上下に意匠を変えて並ぶ。窓間の壁の柱頭飾りや軒持送などの装飾を施してセセッション調にまとめた外観をよく残し、大正期の講堂建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014243"},{"id":"00011712","register_sub_id":"101","register_pk":"210728","name":"愛知県立瑞陵高等学校旧正門門柱（旧愛知県商業学校正門）","kana":"あいちけんりつずいりょうこうとうがっこうきゅうせいもんもんちゅう（きゅうあいちけんしょうぎょうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市瑞穂区北原町二丁目1","lat":35.132053,"lng":136.930269,"geo_status":"db","era":"大正13年頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0482","desc":"敷地南面に建つ。主柱と脇柱各二本からなる鉄筋コンクリート造モルタル仕上げの門。外観はセセッション風に直線で構成され、柱身部は目地を切り、柱頭部には幾何学模様の装飾を付す。かつては柱頂部に丸い照明器具があった。愛知県営繕課による標準設計の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011712"},{"id":"00011717","register_sub_id":"101","register_pk":"210733","name":"愛知県立津島高等学校正門門柱（旧愛知県津島中学校正門）","kana":"あいちけんりつつしまこうとうがっこうせいもんもんちゅう（きゅうあいちけんつしまちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県津島市宮川町三丁目80","lat":35.165612,"lng":136.715932,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0487","desc":"ほぼ正方形の平面の鉄筋コンクリート造モルタル仕上げで、高さは主柱が三・五メートル、脇柱三・一メートルで、同じ意匠でまとめるが、高さ方向の目地間隔を変えている。柱頭部に幾何学模様を配し、三層構成を基調とする門で、学校の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011717"},{"id":"00011722","register_sub_id":"101","register_pk":"210738","name":"愛知県立西尾高等学校通用門門柱（旧愛知県西尾中学校正門）","kana":"あいちけんりつにしおこうとうがっこうつうようもんもんちゅう（きゅうあいちけんにしおちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県西尾市桜町奥新田2-2","lat":34.882286,"lng":137.055667,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、間口9.1m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0492","desc":"鉄筋コンクリート造で、主柱、脇柱各二本からなり、主柱高さは三・〇メートル。副柱は主柱の八割程度の規模とする。愛知県立高校の正門に標準的な手法をとりながら、柱をやや太くし、柱頭部の装飾はアカンサスの葉を模し、古典的要素を強く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011722"},{"id":"00011716","register_sub_id":"101","register_pk":"210732","name":"愛知県立半田商業高等学校正門門柱（旧愛知県知多郡立高等女学校正門）","kana":"あいちけんりつはんだしょうぎょうこうとうがっこうせいもんもんちゅう（きゅうあいちけんちたぐんりつこうとうじょがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県半田市白山町二丁目30","lat":34.891659,"lng":136.923979,"geo_status":"db","era":"大正10年／平成7年改修、平成20年移設","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"コンクリート造、間口9.8m、東西脇柱付","structure_material":"コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0486","desc":"小口煉瓦タイルに花崗岩を帯状に三箇所組み合わせる意匠が特徴で、「赤門」として親しまれている。主門柱の高さは二・九五メートルで、柱頭部に花崗岩の飾り石を配し、柱頂部に球形照明を置く。脇柱は七割程度の規模で、意匠は主柱と共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011716"},{"id":"00011718","register_sub_id":"101","register_pk":"210734","name":"愛知県立碧南高等学校正門門柱（旧愛知県碧南国民学校正門）","kana":"あいちけんりつへきなんこうとうがっこうせいもんもんちゅう（きゅうあいちけんへきなんこくみんがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県碧南市向陽町四丁目12","lat":34.885392,"lng":136.993923,"geo_status":"db","era":"昭和4年頃／昭和37年頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造、間口6.4m、東西土塁留付","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0488","desc":"敷地南面に建つ。正門は花崗岩製の主柱二本からなる。主柱は平らな石基礎に太い江戸切こぶ出し仕上げの角柱を立てたのみの簡素なものであるが、かつては笠石と球形照明器具があった。改変はあるが学校創立期の歴史を今に伝える門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011718"},{"id":"00001076","register_sub_id":"101","register_pk":"102066","name":"刈谷市郷土資料館（旧亀城小学校本館）","kana":"かりやしきょうどしりょうかん（きゅうきじょうしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県刈谷市城町1-25-1","lat":34.98784944,"lng":136.98636947,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積748㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"23 － 0021","desc":"地方都市における初期鉄筋コンクリート造建築の好例。設計は，元愛知県の技手で，刈谷に設計事務所を開いた大中肇。バットレス付きの玄関ポーチと，木造校舎を踏襲した両翼妻面のデザインに特徴がある。関係者の教育にかける思いが伝わってくる建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001076"},{"id":"00009762","register_sub_id":"101","register_pk":"195591","name":"旧愛知県岡崎師範学校武道場","kana":"きゅうあいちけんおかざきしはんがっこうぶどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市六供町八貫1-1","lat":34.96447593,"lng":137.17086649,"geo_status":"db","era":"大正15／昭和41改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積427㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0383","desc":"校地の北寄りに南北棟で建つ。鉄筋コンクリート造で、外壁に柱や梁形を表し、細部にゼツェッション意匠を取入れる。小屋は引張材である下弦材を鋼材として他を木材とする混構造のトラスを組み、内部の大空間を軽快に見せる。当時先進的な意匠、構造を試みた優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009762"},{"id":"00009461","register_sub_id":"101","register_pk":"194254","name":"旧愛知県第二尋常中学校講堂","kana":"きゅうあいちけんだいにじんじょうちゅうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県岡崎市針崎町字春咲1-1","lat":34.92026901,"lng":137.1627016,"geo_status":"db","era":"明治30年／大正14年移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積347㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0359","desc":"木造平家建、寄棟造桟瓦葺で、南北各二箇所の屋根窓を設ける。西正面に切妻の玄関ポーチを付け、玄関欄間は三心アーチとする。東背面に奉安殿が突出。外壁はドイツ下見板張で上下窓の額縁を延ばしたスティックスタイル。内部は東に演壇をもうけ格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009461"},{"id":"00014244","register_sub_id":"101","register_pk":"509634","name":"旧愛知県半田中学校武道場（七中記念館）","kana":"きゅうあいちけんはんだちゅうがっこうぶどうじょう（ななちゅうきねんかん）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県半田市出口町一丁目30","lat":34.90311389,"lng":136.92191389,"geo_status":"db","era":"大正13年／昭和25年・平成30年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積275㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"23 - 0578","desc":"校地の中央北寄りに建つ鉄筋コンクリート造の旧武道場。半切妻造桟瓦葺で、西正面に切妻造玄関突出部を設ける。小屋組は木材と丸鋼による混合トラス構造。縦長窓や柱頭飾り等でセセッションを取り入れて外観をまとめて時代相を示し、同校の長い歴史を語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014244"},{"id":"00006766","register_sub_id":"101","register_pk":"107748","name":"旧起第二尋常小学校奉安殿","kana":"きゅうおこしだいにじんじょうしょうがっこうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市三条字苅2","lat":35.306324,"lng":136.759415,"geo_status":"db","era":"昭和4／昭和22頃移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、建築面積6.7㎡、基壇付","structure_material":"鉄筋コンクリート造","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0253","desc":"三條神社境内、本殿の近い位置に並行して建つ。桁行２．９ｍ、梁間２．３ｍ、入母屋造妻入銅板葺とする。長押が廻り、柱上に舟肘木、一軒疎垂木という木造意匠をコンクリート造で表現する。当初の姿を伝えるコンクリート造の奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006766"},{"id":"00000969","register_sub_id":"101","register_pk":"101959","name":"金城学院高等学校榮光館","kana":"きんじょうがくいんこうとうがっこうえいこうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区白壁4-64","lat":35.18297743,"lng":136.91859399,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積800㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.12.11(平成10.12.11)","register_no":"23 － 0016","desc":"生徒が一同に参集できる規模となるよう計画し，学園関係者等の寄付で再建した。屋根に赤いスペイン瓦を用い，外壁を白系統に塗ったスパニッシュスタイルになる清楚な外観が特徴で，礼拝堂を兼ねる。基本設計は佐藤鑑，実施設計は城戸武男，施工は広瀬商会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000969"},{"id":"00009975","register_sub_id":"101","register_pk":"196122","name":"設楽町立田峯小学校特別教室棟","kana":"したらちょうりつだみねしょうがっこうとくべつきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県北設楽郡設楽町田峯字下畑14他","lat":35.05723798,"lng":137.53270845,"geo_status":"db","era":"昭和2／平成23改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0402","desc":"普通教室棟の西昇降口から渡廊下を介して建つ。木造平屋建で東面し、外壁は普通教室棟と同様の下見板張とする。現在は図工美術室や理科室を配するが、もとは畳敷の裁縫室などであった。普通教室棟とともに、昭和初期における山村の小学校の情景を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009975"},{"id":"00009974","register_sub_id":"101","register_pk":"196121","name":"設楽町立田峯小学校普通教室棟","kana":"したらちょうりつだみねしょうがっこうふつうきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県北設楽郡設楽町田峯字下畑14他","lat":35.05747755,"lng":137.53275303,"geo_status":"db","era":"昭和2／平成23改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積689㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0401","desc":"山間部の田峯集落の校地に南面して建つ。桁行六五メートルに及ぶ、平屋建で片廊下式の木造校舎である。外壁は下見板張で正面中央に切妻造の玄関を構える。今なお現役使用の木造校舎であるとともに、集落内の地域活動の拠点としても活用され、親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009974"},{"id":"00002258","register_sub_id":"101","register_pk":"103248","name":"滝学園講堂","kana":"たきがくえんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県江南市東野町米野1","lat":35.335815,"lng":136.856033,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート一部鉄骨造2階建、セメント瓦葺、建築面積626㎡","structure_material":"鉄筋コンクリート一部鉄骨造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"23 － 0057","desc":"滝学園は名古屋の豪商滝信四郎が創設した。講堂は鉄筋コンクリート造，屋根鉄骨トラス組で本館前広場の東側に建つ。無装飾に近い点が特徴で，正面に設けられた額縁を廻した３連出入口や，ペディメント風の屋根妻面などが，象徴性のある形態を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002258"},{"id":"00011723","register_sub_id":"101","register_pk":"210739","name":"滝学園図書館","kana":"たきがくえんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県江南市東野町米野1","lat":35.335921,"lng":136.856245,"geo_status":"db","era":"昭和8年／昭和40年増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造2階建、鋼板葺、建築面積307㎡","structure_material":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0493","desc":"滝学園講堂の東に接して建つ。一階部分は講堂と同時期に建てられた図書館で閲覧室、カウンターなどの痕跡を残す。これを覆う形で増築された二階部分は戦後モダニズムの特色をよく示し、縦ルーバーが並ぶ立面、ガラス窓を広くとった明るい閲覧室が特色である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011723"},{"id":"00002257","register_sub_id":"101","register_pk":"103247","name":"滝学園本館","kana":"たきがくえんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県江南市東野町米野1","lat":35.335369,"lng":136.855957,"geo_status":"db","era":"昭和1","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、鋼板葺、建築面積1482㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"23 － 0056","desc":"鉄筋コンクリート造，２階建，長大な主屋の両端に短い翼屋をつけた平面。簡明なデザインであるが，正面中央の頂部ペディメント付の玄関突出部，大屋根中央の時計塔など，地域の景観のシンボルとなっている。設計は村瀬國之助，施工は名古屋の安藤建設という。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002257"},{"id":"00000790","register_sub_id":"101","register_pk":"101780","name":"東海学園大講堂","kana":"とうかいがくえんだいこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区筒井1-202-4","lat":35.18000775,"lng":136.92943111,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地下１階地上３階建，建築面積909㎡","structure_material":"鉄骨鉄筋コンクリート造地下１階地上３階建","registered":"1998.09.02(平成10.09.02)","register_no":"23 － 0013","desc":"昭和天皇即位の御大典記念の建造物。ライト調をベースにドイツ表現派の意匠を重ね合わせた意欲的な作品。重厚にして華やかなファサードのデザインに見所がある｡設計は愛知県営繕課長の酒井勝で,卒業生の大脇勲（ともに名高工卒）らが手助けしたとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000790"},{"id":"00011514","register_sub_id":"101","register_pk":"210542","name":"豊田市藤岡民俗資料館（旧藤岡中学校特別教室棟）","kana":"とよたしふじおかみんぞくしりょうかん（きゅうふじおかちゅうがっこうとくべつきょうしつとう）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県豊田市藤岡飯野町井ノ脇401","lat":35.20054389,"lng":137.20762306,"geo_status":"db","era":"昭和29年／昭和56年増築、平成26年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積342㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0477","desc":"旧藤岡町の中心地に位置する。桁行三六メートル、梁間九・四メートル、木造平屋建、切妻造桟瓦葺で南北棟で建つ。小屋組はキングポストトラス。外壁は下見板張で、東面には出窓を設け、ガラス窓を多用し、採光に工夫を凝らす。特別教室棟の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011514"},{"id":"00010978","register_sub_id":"101","register_pk":"208948","name":"豊橋市民俗資料収蔵室西棟（旧多米小学校西校舎）","kana":"とよはししみんぞくしりょうしゅうぞうしつにしとう（きゅうためしょうがっこうにしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県豊橋市多米町字滝ノ谷34-1-1","lat":34.762261,"lng":137.45007,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"23-0459","desc":"本棟の西側に校庭を囲むようにして、南北棟で建つ。桁行三四メートル、梁間九メートルで、北端間を土間とし、西側に廊下を通す。各室東面に出窓を設けて採光に工夫する。室内天井に塗装を施すなど、本棟と比較して、洋風意匠を意識し、地域の教育史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010978"},{"id":"00010977","register_sub_id":"101","register_pk":"208947","name":"豊橋市民俗資料収蔵室本棟（旧多米小学校本校舎）","kana":"とよはししみんぞくしりょうしゅうぞうしつほんとう（きゅうためしょうがっこうほんこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市多米町字滝ノ谷34-1-1","lat":34.762525,"lng":137.450504,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積618㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"23-0458","desc":"多米街道沿いに校地を構える。本棟は、桁行六二メートル、梁間一〇メートルの平屋建校舎で、北に廊下を通す。当時の学校建築に標準とされた方杖が用いられており、内観の特徴となる。西棟とともに市内に唯一残る木造校舎群で、歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010977"},{"id":"00006336","register_sub_id":"101","register_pk":"107319","name":"名古屋大学医学部附属病院門及び外塀（旧愛知県立医学専門学校正門及び外塀）","kana":"なごやだいがくいがくぶふぞくびょういんもんおよびそとべい（きゅうあいちけんりついがくせんもんがっこうせいもんおよびそとべい）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞町65","lat":35.1575169,"lng":136.91980303,"geo_status":"db","era":"大正3／昭和5・平成11改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門 石造門柱2基、間口4.2m、塀 煉瓦造、総延長16m","structure_material":"門 石造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0246","desc":"名古屋大学鶴舞キャンパス敷地の南辺にあり、道路を挟んで鶴舞公園に面する。門柱は花崗岩の方柱で、中央２本が当初のものである。塀は当初の煉瓦造に昭和５年にスクラッチタイルとテラコッタで改修し仕上げたもので、当時のデザイン傾向が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006336"},{"id":"00008696","register_sub_id":"101","register_pk":"149417","name":"名古屋大学豊田講堂","kana":"なごやだいがくとよだこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区仁座町1","lat":35.15333087,"lng":136.96800455,"geo_status":"db","era":"昭和35年／平成2年・平成19年改修","year":1960,"year_source":"converted","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積2981㎡、デッキ広場及びアプローチ付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0333","desc":"名古屋大学東山キャンパス内に、丘陵を背にして建つ。鉄筋コンクリート造3階地下1階建、前面に人工地盤に造られた広場を設置。コンクリート打放し仕上げを基本とし、右手にピロティ、左手に大規模なホールを配する。モダニズム建築の一つの到達点を示す作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008696"},{"id":"00000791","register_sub_id":"101","register_pk":"101781","name":"南山学園ライネルス館","kana":"なんざんがくえんらいねるすかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区五軒家町6-1","lat":35.14259749,"lng":136.95128417,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，建築面積529㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.09.02(平成10.09.02)","register_no":"23 － 0014","desc":"学園創立時(当時は南山中学校)の本館で，現名称は創立者に因む。スイス人建築家ヒンデルの設計で，外壁の色合いはヒンデル好みの黄土色。玄関ポーチの円柱と外壁柱型の横目地が目を惹く。パラペットの三角切り込みは特異で類例を見ない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000791"},{"id":"00003676","register_sub_id":"101","register_pk":"104666","name":"明治村宗教大学車寄","kana":"めいじむらしゅうきょうだいがくくるまよせ","category":"学校","subcategory":"その他工作物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34237538,"lng":136.99287472,"geo_status":"db","era":"明治41／昭和55移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0089","desc":"木造平屋建，宝形造，銅板瓦棒葺。元は大学本館車寄で移築時に背面側を正面と同形に仕上げる。花崗岩製腰壁に各隅３本の角柱が建ち，開口部は要石飾付の３心アーチで，迫元の蛇腹を持送りで受ける。柱間の壁は下部が横羽目板，蛇腹上は透彫のパネルを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003676"},{"id":"00003650","register_sub_id":"101","register_pk":"104640","name":"明治村第八高等学校正門","kana":"めいじむらだいはちこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34054113,"lng":136.98867475,"geo_status":"db","era":"明治42／昭和45移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造、間口9.3m、左右袖塀各5.1m及び鉄製門扉付","structure_material":"煉瓦造","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0063","desc":"煉瓦造の門で両側に脇門を備え，脇塀が接続する。門柱は赤煉瓦積角柱で胴部に３条の花崗岩の帯を巡らす。門柱頭部は箱形で蛇腹を廻す。鉄製門扉は戦中に供出されたものを移築時に復原した。細い竪格子を粗く配しており，円環と渦巻の装飾が軽快である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003650"},{"id":"00003857","register_sub_id":"101","register_pk":"104847","name":"明治村第四高等学校武術道場無声堂弓道場","kana":"めいじむらだいよんこうとうがっこうぶじゅつどうじょうむせいどうきゅうどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.342724,"lng":136.99013911,"geo_status":"db","era":"大正6／昭和45移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0091","desc":"木造平屋建，切妻造，桟瓦葺で，的場側に庇がつく。主屋とは出入口の土間を介して接続する。外壁は隅柱付の洋風下見板張で，妻壁上部を漆喰塗真壁造とし，欄間付の引違窓と横長の引違窓を開く。洋風小屋組を使用し，的場に向かった間口一杯５間を無柱とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003857"},{"id":"00003856","register_sub_id":"101","register_pk":"104846","name":"明治村第四高等学校武術道場無声堂主屋","kana":"めいじむらだいよんこうとうがっこうぶじゅつどうじょうむせいどうしゅおく","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34281804,"lng":136.99041496,"geo_status":"db","era":"大正6／昭和45移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積509㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0090","desc":"木造平屋建，切妻造，桟瓦葺。正面中央に切妻造玄関がつく。内部は剣道場と柔道場に二分し，両妻の落ち棟に師範台と更衣室，背後に浴室を設ける。外壁は隅柱付の洋風下見板張，小壁は漆喰塗真壁造，欄間付引違窓を開く。洋風小屋組で無柱の空間を実現した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003856"},{"id":"00003661","register_sub_id":"101","register_pk":"104651","name":"明治村第四高等学校物理化学教室","kana":"めいじむらだいよんこうとうがっこうぶつりかがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34144356,"lng":136.9890676,"geo_status":"db","era":"明治23／昭和40移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積454㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0074","desc":"木造平屋建，中央玄関ホールの両側に階段教室を設けて切妻屋根を一段高く造り，左右に寄棟屋根の実験教室を延ばす。外壁は隅柱付の下見板張で，欄間付上げ下げ窓を配し，木造洋風校舎建築の代表例である。棟札に工事監督山口半六，設計久留正道とある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003661"},{"id":"00003660","register_sub_id":"101","register_pk":"104650","name":"明治村千早赤阪小学校講堂","kana":"めいじむらちはやあかさかしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.341366,"lng":136.989853,"geo_status":"db","era":"明治30頃／昭和51移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積463㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0073","desc":"木造２階建，寄棟造，桟瓦葺で，１階を雨天体操場，２階を講堂とする。１階は櫛形アーチの軽快なアーケードを巡らせ，２階は隅柱付の下見板張外壁にペディメント付の上げ下げ窓を配す。棟飾やせいの高い軒蛇腹など，明治期木造洋風建築の特色ある意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003660"},{"id":"00003657","register_sub_id":"101","register_pk":"104647","name":"明治村東京盲学校車寄","kana":"めいじむらとうきょうもうがっこうくるまよせ","category":"学校","subcategory":"その他工作物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.33934983,"lng":136.99101617,"geo_status":"db","era":"明治43／昭和43移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0070","desc":"ハーフチンバー様式の建物の車寄部分を移築，四阿とする。緩い切妻屋根を鉄板葺とし，花弁と渦巻を組合せた屋根飾りを載せる。天井中心飾りと破風を植物意匠で，持送り，柱の頭部と胴部，腰壁を幾何学意匠で飾る。柱に支持されない３連アーチが目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003657"},{"id":"00003652","register_sub_id":"101","register_pk":"104642","name":"明治村三重県尋常師範学校・蔵持小学校","kana":"めいじむらみえけんじんじょうしはんがっこう・くらもちしょうがっこう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.3401419,"lng":136.98797513,"geo_status":"db","era":"明治21／昭和48移築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積365㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0065","desc":"木造２階建，桟瓦葺，外壁は玄関部が漆喰塗，教室部が下見板張。軒先持送りと胴蛇腹の下に飾りパネルを付け，簡素な上げ下げ窓を配す。玄関部と１階廊下にトスカナ式円柱を配し，入母屋破風とポーチ扁平アーチを植物意匠で飾る。設計は三重県技師の清水義八。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003652"},{"id":"00009780","register_sub_id":"101","register_pk":"195609","name":"朝日小学校円形校舎","kana":"あさひしょうがっこうえんけいこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県三重郡朝日町大字柿750","lat":35.0339013,"lng":136.66502723,"geo_status":"db","era":"昭和37／平成15改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造4階建、金属板葺、建築面積573㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0165","desc":"町域のほぼ中心に所在する小学校で、四階建の円形校舎に特別教室等を配する。一階から三階は中央に無柱の円形ホール、その周囲に特別教室等を配し、外周にベランダを廻す。四階講堂は一室の大空間を実現する。坂本鹿名夫による一連の円形校舎の中で最盛期の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009780"},{"id":"00010177","register_sub_id":"101","register_pk":"198010","name":"旧阿下喜小学校門及び石柵","kana":"きゅうあげきしょうがっこうもんおよびせきさく","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県いなべ市北勢町阿下喜字二俣1988他","lat":35.15151171,"lng":136.5192147,"geo_status":"db","era":"明治後期／大正10・大正15改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"正門 石造、間口6.0m 門 石造、間口2.8m 石柵 石造、総延長71m","structure_material":"正門 石造","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0181","desc":"旧校地の南辺を画す石造の門と石柵で、中央に正門を、西方に門を開く。正門は花崗岩の石柱を立てて宝形造の笠石を載せ、左右に控石柱を添える。門も同型式でやや小振りとする。石柵は石積基壇上に配列した石柱に鉄棒を渡す。明治開校時の面影を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010177"},{"id":"00009030","register_sub_id":"101","register_pk":"162390","name":"旧尾呂志中学校校舎","kana":"きゅうおろしちゅうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県南牟婁郡御浜町大字上野下尾﨑240-2","lat":33.84570992,"lng":135.98268284,"geo_status":"db","era":"昭和24年／平成16年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積619㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0120","desc":"山中の集落の高台に位置する。南に運動場を設け、北の一段高い位置に建つ。桁行６２ｍ梁間１０ｍの細長い建物で、切妻造桟瓦葺。南面に教室を並べ、北側に廊下を通し、中央西寄りに切妻造妻入の玄関を設ける。緑の山並に長く延びる校舎が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009030"},{"id":"00008010","register_sub_id":"101","register_pk":"128841","name":"旧鳥羽小学校校舎","kana":"きゅうとばしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県鳥羽市鳥羽3-1-60","lat":34.48038676,"lng":136.84473996,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1087㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2010.01.15(平成22.01.15)","register_no":"24-0086","desc":"鳥羽港を望む高台に南面して建つ。正面６７ｍ、Ｅ字形平面の鉄筋コンクリート造３階建で、表面はモルタル仕上げとする。中央３階部分を背後の斜面上に張り出し、内部を大空間の講堂とする独特の構成。中央部分など随所にアールデコ風の意匠を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008010"},{"id":"00005622","register_sub_id":"101","register_pk":"106610","name":"皇學館大学記念館（旧神宮皇學館大学本館）","kana":"こうがっかんだいがくきねんかん（きゅうじんぐうこうがくかんだいがくほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊勢市神田久志本町1704","lat":34.48660585,"lng":136.72627905,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積647㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"24 － 0061","desc":"細長い東西棟，桟瓦葺の建物で，正面の東面は入母屋造で唐破風造，銅板葺の玄関を備え，西面は寄棟造とする。内部はもと中廊下式で左右に教室を配した。縦長窓を配し調和のとれた外観や旧貴賓室と旧館長室の内装に当初形式をよく残す。大正期の和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005622"},{"id":"00007750","register_sub_id":"101","register_pk":"108731","name":"白川小学校校舎北棟","kana":"しらかわしょうがっこうこうしゃきたとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県亀山市白木町2739","lat":34.88339925,"lng":136.41274262,"geo_status":"db","era":"昭和29／平成4改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積573㎡、渡廊下3棟付","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"24-0080","desc":"南棟の北に中庭を挟み平行に建ち、中央及び東西端の渡廊下で繋がる。桁行５８ｍ梁間９．２ｍの木造平屋建、切妻造桟瓦葺で両端に庇を設ける。外壁は上部を白漆喰塗とする下見板張。北側の校庭に面して廊下が通り、南に教室を並べる。地域に親しまれる学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007750"},{"id":"00007749","register_sub_id":"101","register_pk":"108730","name":"白川小学校校舎南棟","kana":"しらかわしょうがっこうこうしゃみなみとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県亀山市白木町2739","lat":34.88323728,"lng":136.41276576,"geo_status":"db","era":"昭和29／平成4改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積586㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"24-0079","desc":"集落北側山中に校地を占める。桁行５８ｍ梁間９．２ｍ、木造平屋建、東西棟の切妻造桟瓦葺で、両端に庇を付ける。上部白漆喰塗の下見板張。片廊下式で、東半に職員室など、西半に教室を配する。正面中央に千鳥破風と玄関ポーチを付け、学校らしい正面性を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007749"},{"id":"00001115","register_sub_id":"101","register_pk":"102105","name":"鈴鹿峠自然の家（旧坂下尋常高等小学校）","kana":"すずかとおげしぜんのいえ（きゅうさかしたじんじょうこうとうしょうがっこう）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県亀山市関町沓掛123","lat":34.88263135,"lng":136.36020234,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積939㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"24 － 0022","desc":"木造平屋建、片廊下４教室規模の校舎２棟を並べ建て、左右を片流れ屋根の廊下でつないだロの字型プランを採っているのが特徴。正面中央に妻をハーフティンバー風にみせた車寄をつける。廃校後も宿泊研修施設として活用され、地区の心の故郷たり続けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001115"},{"id":"00008704","register_sub_id":"101","register_pk":"149425","name":"誓元寺光雲殿（旧常磐尋常高等小学校奉安殿）","kana":"せいげんじこううんでん（きゅうときわじんじょうこうとうしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市赤堀2-2009-1","lat":34.96053225,"lng":136.60667312,"geo_status":"db","era":"昭和10年／昭和21年移築・平成16年改修","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積23㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0102","desc":"境内の南寄りに位置する。切石積基壇上に建つ鉄筋コンクリート造平屋建。4隅に柱型を造り出し、正面に切妻破風を飾る持送り庇を突出する。屋根は陸屋根軒を左右に出し、中央をドーム状に造る。外壁はモルタル洗出し。簡明な意匠でまとめられたRC造奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008704"},{"id":"00010176","register_sub_id":"101","register_pk":"198009","name":"桐林館（旧阿下喜小学校校舎）","kana":"とうりんかん（きゅうあげきしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県いなべ市北勢町阿下喜字二俣1974他","lat":35.152473,"lng":136.519362,"geo_status":"db","era":"昭和12／昭和58移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積345㎡、塔屋付","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0180","desc":"旧校地の北奥に南面し、木造平屋建、寄棟造桟瓦葺である。南面中央に切妻造の玄関を構え、屋根の中央に塔屋を載せ、左右にドーマー窓を飾る。外壁の腰を下見板張とし、小屋はキングポストトラスを組む。外観や内部造作とも旧規をよくとどめる戦前の木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010176"},{"id":"00011973","register_sub_id":"101","register_pk":"211162","name":"福徳公民館（旧明村立明小学校福徳分教場）","kana":"ふくとくこうみんかん（きゅうあきらそんりつあきらしょうがっこうふくとくぶんきょうじょう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県亀山市関町福徳字下垣内143-1","lat":34.835002,"lng":136.378914,"geo_status":"db","era":"昭和25年頃／昭和50年・平成20年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"24-244","desc":"市南西部の山村集落に建つ旧分教場。片廊下を通し、南面に教室一室と一〇畳で床の間をもつ和室を配し、両端に倉庫や物置・便所を備える。最小規模ながら正面に玄関を張り出し格天井とし、外壁は下見板張で窓を大きく開き、学校建築としての意匠をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011973"},{"id":"00002629","register_sub_id":"101","register_pk":"103619","name":"三重大学三翠会館","kana":"みえだいがくさんすいかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県津市上浜町1515","lat":34.74567,"lng":136.521744,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積309㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"24 － 0041","desc":"三重高等農林学校の開校１０周年事業として建設された同窓会館。木造，鉄板葺（旧スレート葺）で西面して建ち，２階建で正面に車寄を突出した主体部の南に平屋の会議室棟を付属する。外壁に柱型や窓枠を多用し，変化に富んだ屋根を載せ派手な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002629"},{"id":"00003243","register_sub_id":"101","register_pk":"104233","name":"三重大学レーモンドホール","kana":"みえだいがくれーもんどほーる","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県津市上浜町1515","lat":34.739643,"lng":136.524628,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積230㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"24 － 0047","desc":"アントニン・レーモンド設計の木造平屋建建築。当初は三重県立大学の図書館として建設された。前面ガラス戸とする開放的南面や丸材を用いる架構等が特徴で，戦前から戦後にかけてに建てられた木造によるレーモンドスタイルの好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003243"},{"id":"00001917","register_sub_id":"101","register_pk":"102907","name":"近江兄弟社学園教育会館","kana":"おうみきょうだいしゃがくえんきょういくかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市市井町177","lat":35.14028676,"lng":136.09548669,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積477㎡","structure_material":"木造平屋一部2階建","registered":"2000.10.18(平成12.10.18)","register_no":"25 － 0138","desc":"ハイド記念館と共にメンソレータム社創設者Ａ．Ａ．ハイド夫人の寄付により建造された講堂兼体育館。外装は記念館に類似。切妻造を基調とし，片側面にＴ形窓を並べ，もう片側を用具室等を収めるために下屋庇状に屋根を一段下げる。妻面に出窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001917"},{"id":"00001916","register_sub_id":"101","register_pk":"102906","name":"近江兄弟社学園ハイド記念館","kana":"おうみきょうだいしゃがくえんはいどきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市市井町177","lat":35.14004831,"lng":136.09547876,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積352㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"25 － 0137","desc":"市中心部に位置する。木造２階建，切妻造・赤桟瓦葺，車寄付で，外装スタッコ仕上，腰下見板張とし，単窓・連窓を巧みに配す。採光や内部機能に優れた近代幼稚園園舎。設計ヴォーリズ。ヴォーリズ夫人で建設当時園長の一柳満喜子が計画に参与したと伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001916"},{"id":"00009506","register_sub_id":"101","register_pk":"194299","name":"旧豊郷小学校校舎","kana":"きゅうとよさとしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町石畑518","lat":35.20339074,"lng":136.23287204,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積1839㎡、渡廊下付","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0330","desc":"旧中山道に面した校地の中央に西面して建つ。鉄筋コンクリート造二階建、建築面積一、八七九平方メートル、中央部を三階建の塔屋として正面に車寄を出す。モダニズムを基調とした左右対称の威風堂々とした外観は、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009506"},{"id":"00009507","register_sub_id":"101","register_pk":"194300","name":"旧豊郷小学校講堂","kana":"きゅうとよさとしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町石畑518","lat":35.20305761,"lng":136.23212965,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建一部地階付、建築面積519㎡","structure_material":"鉄筋コンクリート造平屋一部2階建一部地階付","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0331","desc":"校舎の南側前方に北面して建ち、渡り廊下で接続する。鉄筋コンクリート造二階建、建築面積五一八平方メートル、南端の地下にボイラー室を設ける。校舎と同様のモダニズムを基調とした整然とした外観で、校舎、図書館とともに建設当時の威容を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009507"},{"id":"00009508","register_sub_id":"101","register_pk":"194301","name":"旧豊郷小学校酬徳記念図書館","kana":"きゅうとよさとしょうがっこうしゅうとくきねんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町石畑518","lat":35.20401178,"lng":136.23292915,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積355㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0332","desc":"校舎の北側前方に南面して建ち、校舎とは渡り廊下で接続する。鉄筋コンクリート造二階建、建築面積三五五平方メートル、北側の中央部を鉄製三層の本棚を組み込んだ書庫にあてる。外観は校舎に合わせるが、柱頭や手摺りの金具に飾り気のある意匠を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009508"},{"id":"00006318","register_sub_id":"101","register_pk":"107301","name":"旧豊郷尋常高等小学校本館","kana":"きゅうとよさとじんじょうこうとうしょうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院815","lat":35.20653664,"lng":136.23573131,"geo_status":"db","era":"明治20／昭和12改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0241","desc":"至熟小学校講堂として建設。敷地東奥に西を正面にして建つ桁行７間，梁間４間の木造２階建で，寄棟造，桟瓦葺とする。外壁はモルタル塗で，両開ガラス窓を開く。正面中央の車寄上部のバルコニーにはロクロ挽手摺子を飾り，ペディメント風の切妻屋根を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006318"},{"id":"00000446","register_sub_id":"101","register_pk":"101436","name":"湖東町歴史民俗資料館（旧西押立国民学校校舎）","kana":"ことうちょうれきしみんぞくしりょうかん（きゅうにしおしたてこくみんがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市北菩提寺町126","lat":35.1432793,"lng":136.23699843,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階建，瓦葺，建築面積676㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0027","desc":"実業家松居泰次良・房治郎兄弟の寄付により建設された。コの字形平面の建物で，外壁の下見板と屋根の赤色の桟瓦の対比に特徴がある。大工は泰山閣と同じ木村太兵衛である。昭和56年に資料館となったが，強度の木造校舎として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000446"},{"id":"00002149","register_sub_id":"101","register_pk":"103139","name":"滋賀大学経済学部講堂（旧彦根高等商業学校講堂）","kana":"しがだいがくけいざいがくぶこうどう（きゅうひこねこうとうしょうぎょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市馬場1-1-1","lat":35.276863,"lng":136.247116,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積679㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"25 － 0143","desc":"彦根城西部の堀に接する滋賀大学敷地内にある。木造２階建の講堂に，平屋建の大教室が接続し，外装ほぼ全体を下見板貼とする。講堂妻面に柱型付玄関を設け，上下階で連続性をもつ矩形窓を側面に配し，半円形屋根窓，瀟洒な小塔を冠す。文部省建築課の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002149"},{"id":"00001116","register_sub_id":"101","register_pk":"102106","name":"曽根東福寺組地蔵堂（旧曽根学校玄関）","kana":"そねとうふくじくみじぞうどう（きゅうそねがっこうげんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市曽根町992-1","lat":35.40819938,"lng":136.25120398,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積５㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"25 － 0111","desc":"明治９年に建築された曽根学校の旧校舎玄関部分を分離し、地蔵堂として利用したもの。間口１間で、正面の礎盤付きの円柱上部に組物を置き、両折の桟唐戸を付け円弧状の瓦屋根を乗せた特異な旧態が保たれている。村の辻堂として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001116"},{"id":"00001915","register_sub_id":"101","register_pk":"102905","name":"長浜旧開知学校","kana":"ながはまきゅうかいちがっこう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市元浜町2-3","lat":35.379448,"lng":136.267365,"geo_status":"db","era":"明治7／昭和11移築","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造3階建、瓦葺、建築面積127㎡、塔屋付","structure_material":"木造3階建","registered":"2000.10.18(平成12.10.18)","register_no":"25 － 0136","desc":"駅前通り沿いに建つ木造３階建，八角塔屋付の擬洋風建築。外装モルタル塗，腰石積，隅石付。正面入口とその上部に列柱式開口部を構え，壁面に上げ下げ窓と花形レリーフを均等に配す。学校施設として利用された後，近年改修され，現在展示・会議室として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001915"},{"id":"00000691","register_sub_id":"101","register_pk":"101681","name":"白雲館","kana":"はくうんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市為心町元９－１","lat":35.13944061,"lng":136.09100612,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造２階建，瓦葺，建築面積306㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0039","desc":"八幡東学校として建設。日牟礼八幡宮参道の鳥居前に位置し，主屋に翼舎をはりだした凹字形の形態をとる。漆喰塗系の擬洋風建築で玄関上部の唐破風と屋根上の太鼓楼との取り合わせは開智学校の造形に類似している。棟梁は近江蒲生郡の大工高木作右衛門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000691"},{"id":"00000447","register_sub_id":"101","register_pk":"101437","name":"錬成館（旧西押立国民学校講堂）","kana":"れんせいかん（きゅうにしおしたてこくみんがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市北菩提寺町126","lat":35.14308453,"lng":136.23733261,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積534㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0028","desc":"校舎と同時期に建てられた講堂を，移築にともない柔道場としたもの。袴腰の大屋根の正面に一段低い屋根や車寄せ等を設け，正面からは複雑にみえるようにしている。外壁に下見板を張り（現在は一部モルタル）屋根に赤色の桟瓦を葺く意匠は校舎に類似する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000447"},{"id":"00003451","register_sub_id":"101","register_pk":"104441","name":"大阪医科大学看護専門学校校舎（旧大阪高等医学専門学校別館）","kana":"おおさかいかだいがくかいごせんもんがっこうこうしゃ（きゅうおおさかこうとういがくせんもんがっこうべっかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府高槻市大学町2-7","lat":34.851574,"lng":135.625916,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積325㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0244","desc":"ヴォーリズ建築事務所の設計による医学専門学校の別館。鉄筋コンクリート造３階建で，玄関部にロンバルディア帯，バトルメント状の装飾を施すほか，窓部のオジーアーチや葱花ドームなどイスラム様式を採り入れている。地域の歴史的建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003451"},{"id":"00002644","register_sub_id":"101","register_pk":"103634","name":"大阪市立大学本館（一号館）","kana":"おおさかいちりつだいがくほんかん（いちごうかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区杉本三丁目４５９－１５他","lat":34.59060561,"lng":135.50504007,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積2522㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0165","desc":"大阪商科大学本館として建設された鉄筋コンクリート造の建物。南面し，東西に長く伸ばした翼部，背面に講堂を接続し，正面中央玄関上部に塔を高く聳える。全体にクラシックな構成だが，簡略化した柱型や庇による水平線の強調などによる新たな造形志向が顕著。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002644"},{"id":"00004998","register_sub_id":"101","register_pk":"105988","name":"大阪歯科大学牧野学舎本館","kana":"おおさかしかだいがくまきのがくしゃほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府枚方市牧野本町1-4-4","lat":34.84073596,"lng":135.66966935,"geo_status":"db","era":"昭和4／昭和37増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1049㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0330","desc":"鉄筋コンクリート造３階建で，正面中央に塔を立ち上げ，左右に翼部を張り出したほぼ左右対称の建築構成をとる。幾条にも廻した水平帯と西面２階３階の曲面をもつ出窓の表現派風造形意匠に特徴。設計は大林組の今林彦太郎で，施工も大林組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004998"},{"id":"00011531","register_sub_id":"101","register_pk":"210481","name":"大阪女学院ヘールチャペル","kana":"おおさかじょがくいんへーるちゃぺる","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区玉造二丁目26-15","lat":34.67691611,"lng":135.527215,"geo_status":"db","era":"昭和26年／昭和59年増築、平成13年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋一部3階建、建築面積727㎡","structure_material":"鉄骨鉄筋コンクリート造平屋一部3階建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0664","desc":"大阪城公園の南方に校地を構える。ヴォーリズ建築事務所の設計による鉄骨鉄筋コンクリート造の礼拝堂と講堂を兼ねた施設。オーディトリアムでは天井を高くして広がりのある上質な空間を実現する。外観は装飾要素を抑えたモダニズム意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011531"},{"id":"00004147","register_sub_id":"101","register_pk":"105137","name":"大阪大学共通教育本館","kana":"おおさかだいがくきょうつうきょういくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府豊中市待兼山町1-1","lat":34.806614,"lng":135.452484,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積1276㎡、塔屋付","structure_material":"鉄筋コンクリート造4階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0290","desc":"旧制浪速高等学校校舎として建設。鉄筋コンクリート造で，南面する４階建，塔屋付の南棟の北面西端に，３階建の北棟が続きＬ字形平面をつくる。平明ながら尖頭形の窓や塔屋部等のネオゴシック風の外観意匠に特徴がある。大阪府営繕課の設計で，大林組の施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004147"},{"id":"00007513","register_sub_id":"101","register_pk":"108495","name":"大阪府立桜塚高等学校塀（旧豊中高等女学校周塀）","kana":"おおさかふりつさくらづかこうとうがっこうへい（きゅうとよなかこうとうじょがっこうしゅうべい）","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府豊中市中桜塚4-1-1","lat":34.78359025,"lng":135.47168872,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造、総延長130m","structure_material":"煉瓦造及び鉄筋コンクリート造","registered":"2009.01.08(平成21.01.08)","register_no":"27 － 0522","desc":"校地の北辺及び南東隅に建ち、総延長１３０ｍである。高さ１．１ｍ煉瓦造の柱の各間に鉄筋コンクリート製のパネルを設け、パネルには一間おきに桜花を象った透かし孔を３ヶ所開ける。高さも抑えめで、もと女学校らしい穏やかで気品のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007513"},{"id":"00004795","register_sub_id":"101","register_pk":"105785","name":"大阪府立四條畷高等学校本館","kana":"おおさかふりつしじょうなわてこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府四條畷市雁屋北町1-1","lat":34.735458,"lng":135.636597,"geo_status":"db","era":"昭和9～11","year":1934,"year_source":"converted","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1581㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0328","desc":"大阪府営繕課の設計により，昭和９年から１１年にかけて２期に分けて建設。柱形を露わにした整然とした立面，玄関廻りの庇，円柱や丸窓の意匠，室内廊下のアーチ状梁形などに特色がある。「質実堅牢」を旨としたモダニズム色の強い昭和初期学校建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004795"},{"id":"00001529","register_sub_id":"101","register_pk":"102519","name":"大阪府立三国丘高等学校同窓会館（旧三丘会館）","kana":"おおさかふりつみくにがおかこうとうがっこうどうそうかいかん（きゅうさんきゅうかいかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区南三国ヶ丘町2-2-36","lat":34.573837,"lng":135.488144,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート2階建、建築面積354㎡","structure_material":"鉄筋コンクリート2階建","registered":"2000.02.15(平成12.02.15)","register_no":"27 － 0088","desc":"旧制堺中学校の図書館機能を有する記念館として建設。設計は，同校の１期生で，初代鉄道省建築課長の久野節。玄関庇を支持する先すぼまりの円柱，階段室塔屋の縦長の連続窓と庇の構成などモダニズム色の強い造形に特色が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001529"},{"id":"00005966","register_sub_id":"101","register_pk":"106951","name":"河内長野市立武道館（旧長野町尋常高等小学校講堂）","kana":"かわちながのしりつぶどうかん（きゅうながのちょうじんじょうこうとうしょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市西代町904-1","lat":34.453053,"lng":135.564728,"geo_status":"db","era":"昭和2／昭和52改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積491㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0401","desc":"間口８間，奥行１５間，木造平屋建，銅板葺で，背面に奥行２間の瓦葺下屋が付く。屋根は半切妻で，外壁は上壁をハーフティンバー風とし，腰壁を板張（鉄板仮張）とする。正面に間口４間，奥行２間，切妻造の玄関を設け，安定感のある洋風の意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005966"},{"id":"00000358","register_sub_id":"101","register_pk":"101348","name":"旧岸和田村尋常小学校校舎","kana":"きゅうきしわだむらじんじょうしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府岸和田市西之内町８","lat":34.46978643,"lng":135.395241,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積185㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"27 － 0025","desc":"木造平屋建，瓦葺の校舎。中央部の玄関から左右に教室をのばした左右対称の形態や教室に採光するための大きな窓を持つ外観の意匠に特徴がある。明治期に建設された小規模な学校建築の好例で，現在は岸和田市中央公園に移築保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000358"},{"id":"00014192","register_sub_id":"101","register_pk":"508822","name":"旧京都大学高槻農場加工室","kana":"きゅうきょうとだいがくたかつきのうじょうかこうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.85543611,"lng":135.63064722,"geo_status":"db","era":"昭和8年／同10年増築・令和2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積303㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0842","desc":"大学農場本館の西側に建つ。平屋建切妻造金属板葺。外壁は漆喰仕上で腰下はモルタル仕上。南・東・北棟からなるコ字形平面で、内部は一部に床を張り打上天井、その他は土間で小屋組のキングポスト・トラスを現す。コテージ風意匠で縦長窓が並ぶ農場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014192"},{"id":"00014193","register_sub_id":"101","register_pk":"508823","name":"旧京都大学高槻農場農具舎","kana":"きゅうきょうとだいがくたかつきのうじょうのうきぐこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.8557,"lng":135.63085556,"geo_status":"db","era":"昭和5年／令和2年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0843","desc":"大学農場本館の背面側に建つ。平屋建、切妻造金属板葺。南北棟で東側に庇を延ばし出入口とする。壁は漆喰仕上、腰下モルタル洗出し。妻壁上部に円形通気口を設置。内部は土間で、南半に根太天井を張り、北半はトラス組を現す。真壁造で他施設と意匠を変える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014193"},{"id":"00014191","register_sub_id":"101","register_pk":"508821","name":"旧京都大学高槻農場別館","kana":"きゅうきょうとだいがくたかつきのうじょうべっかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.85540278,"lng":135.63132222,"geo_status":"db","era":"昭和7年／令和2年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0841","desc":"大学農場本館の東側に建つ。平屋建、切妻造赤色桟瓦葺、東西妻面に出入口を設ける。アーチ窓と矩形窓を併置し、繰型付方杖を付し、コテージ風意匠を示す。内部は中廊下に北側３室、南側２室を並べ、天井や金物に幾何学調意匠を凝らす。瀟洒な農場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014191"},{"id":"00014190","register_sub_id":"101","register_pk":"508820","name":"旧京都大学高槻農場本館及び付属屋","kana":"きゅうきょうとだいがくたかつきのうじょうほんかんおよびふぞくや","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.85541389,"lng":135.63096667,"geo_status":"db","era":"昭和5年／令和2年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積391㎡","structure_material":"木造2階建一部平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0840","desc":"大学農場の旧施設群の本館で安満遺跡に位置する。切妻造赤色桟瓦葺。中央部を２階建とし、正面軒を緩勾配の切妻状に切上げ、玄関にパーゴラ状の庇を付す。背面に平屋建附属屋が建つ。外観は二階に柱形と縦長アーチ窓を配し、スパニッシュを基調とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014190"},{"id":"00009654","register_sub_id":"101","register_pk":"194650","name":"行信教校講堂棟","kana":"ぎょうしんきょうこうこうどうとう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府高槻市東五百住町3-805他","lat":34.8373515,"lng":135.59959435,"geo_status":"db","era":"昭和6／平成5・平成10改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積285㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0569","desc":"敷地中央に東西棟で建ち、木造二階建、寄棟造桟瓦葺である。左右対称平面で、北面中央に唐破風玄関を構える。一階は中廊下式で八畳居室を並べ、生徒室や事務室などとする。二階は畳敷の広い講堂で、西奥に仏壇を構える。類例希な僧侶養成専門学校の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009654"},{"id":"00009655","register_sub_id":"101","register_pk":"194651","name":"行信教校専精会館","kana":"ぎょうしんきょうこうせんしょうかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市東五百住町3-805","lat":34.83716828,"lng":135.59987751,"geo_status":"db","era":"昭和6／平成5・平成10改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0570","desc":"敷地南東に建ち、木造二階建、宝形造桟瓦葺で、東西面の戸口に半切妻の庇を付ける。略正方形平面で、一階は中廊下の両側に四室を配する。二階は三六畳の講義室で格天井を張り、北面中央に仏壇を備える。講堂棟とともに昭和初期の僧侶養成学校の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009655"},{"id":"00005480","register_sub_id":"101","register_pk":"106468","name":"樟蔭学園記念館","kana":"しょういんがくえんきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西4-258-1","lat":34.66320529,"lng":135.57794648,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積449㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0367","desc":"木造２階建，寄棟造，鋼板葺で，外壁は目地切のモルタル仕上げとする。南面西寄りに玄関をわずかに突出させ，角塔と駒形の破風で飾る。南東隅部も角塔に扱い，２階窓は３連アーチとする。当初は１階が図書室と書庫，２階が大講義室と会議室兼来賓室であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005480"},{"id":"00006282","register_sub_id":"101","register_pk":"107266","name":"樟蔭学園樟古館旧試食室","kana":"しょういんがくえんしょうこかんきゅうししょくしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府東大阪市菱屋西4-258-1","lat":34.66275642,"lng":135.57700725,"geo_status":"db","era":"大正7／昭和44曳家","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0428","desc":"家事実習室として建設。旧洗濯室の南に並ぶ木造平屋建である。方２間半の妻入で，半切妻屋根をかけるが，軒反りをつけてオランダ風につくる。外壁は構造材を現した簡素なスティックスタイル。ポーチの切妻屋根と南面の出窓が小建築にアクセントを与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006282"},{"id":"00006281","register_sub_id":"101","register_pk":"107265","name":"樟蔭学園樟古館旧洗濯室","kana":"しょういんがくえんしょうこかんきゅうせんたくしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府東大阪市菱屋西4-258-1","lat":34.66282365,"lng":135.57698973,"geo_status":"db","era":"大正7／昭和44曳家","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0427","desc":"家事実習室として建設。東を正面に建つ木造平屋建で，桁行７間，梁間５間の矩形平面であるが，寄棟屋根に半切妻を組合せて屋根形態に変化を付けている。外壁は構造材を現した簡素なスティックスタイルで，欄間付の引違窓と腰の縦板張がアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006281"},{"id":"00000141","register_sub_id":"101","register_pk":"101131","name":"聖母女学院校舎","kana":"せいぼじょがくいんこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府寝屋川市美井町1011-6","lat":34.78122863,"lng":135.63620655,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建，建築面積3233㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"1997.05.07(平成9.05.07)","register_no":"27 － 0017","desc":"大正12年に創立された名門女学校の校舎で，均等な日照や通風のとれるフィンガー型の平面配置を採用した初期の例である。設計はアントニン・レーモンド。スパニッシュ風のコロネードとコンポジット式の柱頭を持つ正面入り口が意匠上の特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000141"},{"id":"00001840","register_sub_id":"101","register_pk":"102830","name":"谷岡記念館","kana":"たにおかきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市御厨栄町4-1-10","lat":34.66684231,"lng":135.58416555,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積807㎡、塔屋付","structure_material":"鉄筋コンクリート造4階建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0105","desc":"昭和９年室戸台風後に復興された城東商業学校（現大阪商業大学）校舎で，現在は資料の展示施設として活用。南北に長いＲＣ造４階建で，正面に時計台，内部に３・４階吹抜けの講堂を設ける。平滑な壁面とアーチや丸窓などの意匠に時代の特色がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001840"},{"id":"00002562","register_sub_id":"101","register_pk":"103552","name":"富田林市立川西小学校教育歴史資料室（旧川西尋常小学校）","kana":"とんだばやしりつたちかわにししょうがっこうきょういくれきししりょうしつ（きゅうかわにしじんじょうしょうがっこう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府富田林市新家1-3-1","lat":34.49308,"lng":135.588364,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0164","desc":"昭和９年の室戸台風後の復興校舎で，玄関・職員室と高等科教室１室を残す。教室の天井を船底天井とし，室内天井下に挟み方杖を見せるなどの構造的な特徴のほか，東妻面に玄関ポーチを配して半切妻の２重構成とするなどの意匠的な見所もあわせもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002562"},{"id":"00006268","register_sub_id":"101","register_pk":"107252","name":"尼崎市役所開明庁舎（旧開明尋常小学校校舎）","kana":"あまがさきしやくしょかいめいちょうしゃ（きゅうかいめいじんじょうしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市開明町2-1-1","lat":34.71720031,"lng":135.41592847,"geo_status":"db","era":"昭和12／平成17改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階一部平屋建、建築面積1253㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0273","desc":"ＲＣ造３階建で，敷地の東側と北側にＬ字形平面で建つ。東棟南端から平屋を延ばし，入隅に設けた四半円平面の玄関ホールとその上の半円筒形階段室がアクセントとなる。外壁は矩形窓を整然と配し，窓庇で水平線を強調している。昭和初期のＲＣ造学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006268"},{"id":"00001130","register_sub_id":"101","register_pk":"102120","name":"小林聖心女子学院本館","kana":"おばやしせいしんじょしがくいんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市塔の町125","lat":34.78677085,"lng":135.35005776,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1777㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0046","desc":"レーモンドによる鉄筋コンクリート造学校建築。日の字型プランの２階建及び３階建校舎に教室、図書室、講堂、礼拝堂、寄宿舎などを巧みに納める。レーモンド＆サイクス建築事務所時代の作品で、隅部に曲面を多用するなどライト式からの脱却の跡が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001130"},{"id":"00007787","register_sub_id":"101","register_pk":"108768","name":"関西学院大学時計台（旧図書館）","kana":"かんせいがくいんだいがくとけいだい（きゅうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市上ヶ原一番町2-10","lat":34.76969619,"lng":135.34697065,"geo_status":"db","era":"昭和4／昭和30増築・昭和48・平成7改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階一部地下1階建、瓦葺、建築面積477㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部地下1階建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0413","desc":"甲山を背にキャンパス中央に建つ。南北４７ｍに及ぶ左右対称のＲＣ造２階建で、中央に塔屋とポーチ、両端に切妻屋根を付け、アーチの連窓を配する。赤色の瓦、クリーム色のスタッコ塗壁の対比が鮮やかなスパニッシュ・ミッション・スタイルの学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007787"},{"id":"00014880","register_sub_id":"101","register_pk":"519140","name":"旧尼崎市立高等女学校校舎(尼崎市立歴史博物館・尼崎市立成良中学校琴城分校)","kana":"きゅうあまがさきいちりつこうとうじょがっこうこうしゃ（あまがさきいちりつれきしはくぶつかん・あまがさきいちりつせいりょうちゅうがっこうきんじょうぶんこう）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市南城内10-2","lat":34.71479167,"lng":135.42091944,"geo_status":"db","era":"昭和13年／昭和41年・令和2年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2，106㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0794","desc":"尼崎城本丸跡にある旧女学校校舎。鉄筋コンクリート造3階建でロの字の平面。正面は横長窓を並べて装飾を抑えつつ、中央部を前方にやや突出させ、片持ちの車寄庇を太い円柱で支えるなど外観を特徴づける。市内で数少ない戦前期の校舎で城内地区の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014880"},{"id":"00014881","register_sub_id":"101","register_pk":"519141","name":"旧尼崎市立高等女学校校門","kana":"きゅうあまがさきいちりつこうとうじょがっこうこうもんもんちゅう","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市南城内10-2","lat":34.71523889,"lng":135.42101111,"geo_status":"db","era":"昭和2年／令和2年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造、間口4.0m、東脇柱付","structure_material":"鉄筋コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0795","desc":"校舎の北面に位置する校門。鉄筋コンクリート造、間口４メートルで、親柱を二本立て、東脇柱との間は脇門、西脇柱との間に袖壁を付す。全体に表面を粗く仕上げた石貼とし、親柱上には薄い宝形風屋根を載せる。重厚な外観が城内地区に建つ学校の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014881"},{"id":"00012764","register_sub_id":"101","register_pk":"367667","name":"甲南女子大学管理棟","kana":"こうなんじょしだいがくかんりとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町六丁目2-3","lat":34.703475,"lng":135.26556944,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積867㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 699","desc":"六甲山地南麓のキャンパス中央に南面して建つ。鉄筋コンクリート造3階建、75メートルに及ぶ長大な正面の1・2階壁面を後退して独立柱を並べ、柱にテーパーをつけて細くみせるなど重量感を抑えたデザインでまとめる。大学の顔として親しまれる象徴的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012764"},{"id":"00012765","register_sub_id":"101","register_pk":"367668","name":"甲南女子大学３号館","kana":"こうなんじょしだいがくさんごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町六丁目2-3","lat":34.703475,"lng":135.26556944,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積718㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 700","desc":"管理棟の北側に並行して建つ鉄筋コンクリート造3階建の校舎。窓上に設けた長方形枠の高窓など管理棟と共通の造形表現を基調としつつ、片廊下式の均質な教室配置にあわせて変化を加えたデザインで全体をまとめる。管理棟とともにキャンパスの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012765"},{"id":"00012766","register_sub_id":"101","register_pk":"367669","name":"甲南女子大学渡廊下","kana":"こうなんじょしだいがくわたりろうか","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町六丁目2-3","lat":34.703475,"lng":135.26556944,"geo_status":"db","era":"昭和39年／昭和54年改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、金属板葺、面積470㎡","structure_material":"鉄筋コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 701","desc":"キャンパス中央部を南北に貫通し、管理棟と３号館を接続する鉄筋コンクリート製の階段。中央部を芝生敷として両端に幅2メートルの屋根付の階段を通す。最下部は幅15メートルの大階段とする。管理棟、３号館と一体でキャンパスの基幹部分を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012766"},{"id":"00013287","register_sub_id":"101","register_pk":"366276","name":"甲南女子中学校・高等学校管理棟","kana":"こうなんじょしちゅうがっこう・こうとうがっこうかんりとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73501389,"lng":135.29181667,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積1703㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0731","desc":"甲南女子大学東隣のキャンパス中央に建つ。鉄筋コンクリート造二階建、一階中央部をピロティとして車路を通し、車路の東を主玄関とする。玄関から特別棟へは、回廊をつくり教職員と生徒の動線を巧みに分離する。村野藤吾によるキャンパス計画の中心をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013287"},{"id":"00013291","register_sub_id":"101","register_pk":"366280","name":"甲南女子中学校・高等学校講堂","kana":"こうなんじょしちゅうがっこう・こうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73501389,"lng":135.29226667,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建、石綿セメント板葺、建築面積1010㎡","structure_material":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0735","desc":"管理棟の南側斜面に建つ講堂。六角形平面の北を舞台とし南を台形に突出させて座席とする。平面に対応して屋根を小割にし、その軒を薄くして軽快感を強調している。室内は天井や壁の出隅に曲線を多用する有機的な設えとし、村野藤吾の造形的特徴を伺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013291"},{"id":"00014273","register_sub_id":"101","register_pk":"509663","name":"甲南女子中学校・高等学校茶道教室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうさどうきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町五丁目4-1他","lat":34.73473333,"lng":135.29255833,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0778","desc":"校地東の一角に位置する村野藤吾設計の茶室。平屋建寄棟造桟瓦葺で、銅板葺土庇を南西に付す。内部は玄関、六畳と八畳の座敷を東西に並べ、玄関北に水屋と手洗を突出させる。座敷意匠は平明でガラス戸を採り入れ、モダニズムに通じる和風意匠をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014273"},{"id":"00013292","register_sub_id":"101","register_pk":"366281","name":"甲南女子中学校・高等学校守衛室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうしゅえいしつ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73459722,"lng":135.29250556,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"コンクリートブロック造及び木造平屋建、石綿セメント板葺、建築面積29㎡","structure_material":"コンクリートブロック造及び木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0736","desc":"キャンパス南側の正門脇に設けられた守衛室。平屋建で、コンクリートブロック壁に木造の宝形を組合わせた屋根を架ける。矩折れに取付く出窓や、煉瓦を二段帯状に積込んだブロック積の壁体など、小規模ながらも細部まで意匠的配慮が行き届いた造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013292"},{"id":"00013289","register_sub_id":"101","register_pk":"366278","name":"甲南女子中学校・高等学校体育館","kana":"こうなんじょしちゅうがっこう・こうとうがっこうたいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73487222,"lng":135.29106667,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造2階建、金属板葺、建築面積1080㎡","structure_material":"鉄骨造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0733","desc":"管理棟の西端北側に建つ体育館。鉄骨造二階建で、一階は中廊下で食堂、卓球場を配し、二階は一室とする。矩形平面の四隅に二本ずつ対をなす鋼管柱を八本立て、大梁を対角に架けて47メートルの大スパンを確保し、軽快な架構を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013289"},{"id":"00013290","register_sub_id":"101","register_pk":"366279","name":"甲南女子中学校・高等学校体育研究室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうたいいくけんきゅうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73463611,"lng":135.2912,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造2階建、金属板葺、建築面積40㎡","structure_material":"鉄骨造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0734","desc":"体育館の南西隅に接続する鉄骨造二階建の建物。一階をピロティとし、二階は凸型の平面とする。ピロティの柱はセメント板で被覆した末広がりの角柱とし、二階の連続窓の上に薄い庇を張出し、細い螺旋階段で昇降する軽快なつくりの建物とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013290"},{"id":"00013288","register_sub_id":"101","register_pk":"366277","name":"甲南女子中学校・高等学校特別棟","kana":"こうなんじょしちゅうがっこう・こうとうがっこうとくべつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73533889,"lng":135.29207778,"geo_status":"db","era":"昭和43年／平成24年改修","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積526㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0732","desc":"管理棟の東側に接続して建つ鉄筋コンクリート造4階建の校舎。同一形状の窓が並ぶ立面だが、西側の窓は上下で窓の横幅を変えて凸字型にし、中央部に水平庇を突き出し、両端の外階段のバルコニー腰壁は煉瓦積とするなど、立面に変化を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013288"},{"id":"00014274","register_sub_id":"101","register_pk":"509664","name":"甲南女子中学校・高等学校西門守衛室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうにしもんしゅえいしつ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町五丁目4-1他","lat":34.73532778,"lng":135.29100833,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"コンクリートブロック造及び木造平屋建、スレート葺、建築面積11㎡","structure_material":"コンクリートブロック造及び木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0779","desc":"北西側の西門脇に位置する村野藤吾設計の守衛室。コンクリートブロック造平屋建で、人造スレート葺宝形屋根を載せる。出入口となる東角では入隅にして独立柱を立て、南角では出窓を矩折れに付すなど、小規模ながらも細部にまで意匠的配慮が行き届いた守衛室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014274"},{"id":"00003294","register_sub_id":"101","register_pk":"104284","name":"神戸大学兼松記念館","kana":"こうべだいがくかねまつきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.72933438,"lng":135.23478058,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1172㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0119","desc":"ＲＣ造３階建で，両脇から後方に延びる短い翼部は２階建とする。内部は中廊下式とし，研究室等を収める。市松タイル敷の階段ホール，階段手摺上部の鋳物飾など優れた意匠を持つが，外観意匠は簡素にまとめる。文部省営繕の設計になる学校建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003294"},{"id":"00003293","register_sub_id":"101","register_pk":"104283","name":"神戸大学講堂","kana":"こうべだいがくこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.728329,"lng":135.233932,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積750㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0118","desc":"スクラッチタイル張，ロンバルディア帯など本館と共通の意匠を持つ。奥に演壇を置き，前面側を２階建として聴衆室を設ける。船舶の舵をあしらった両開入口扉を３カ所並べ，両脇と併せて５連の大アーチをもつ正面外壁が，講堂としての強い正面性を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003293"},{"id":"00003295","register_sub_id":"101","register_pk":"104285","name":"神戸大学人文社会系図書館","kana":"こうべだいがくじんぶんしゃかいけいとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.72929,"lng":135.234055,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積904㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0120","desc":"ＲＣ造５階建の図書館建築。外観は下層のみ正方形タイルとし，軒にはロンバルディア帯を廻らす。２階大閲覧室はアーチによる大空間とし，正面階段上部のステンドグラスのトップライトなど意匠を凝らす。室内外とも質の高いデザインを誇る学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003295"},{"id":"00009353","register_sub_id":"101","register_pk":"194146","name":"神戸大学武道場（旧神戸商業大学道場）","kana":"こうべだいがくぶどうじょう（きゅうこうべしょうぎょうだいがくどうじょう）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.73128127,"lng":135.23294358,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積362㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"28 － 0552","desc":"六甲台キャンパスの北西隅に南面して建つ。入母屋造桟瓦葺、桁行二七・三メートル梁間一二・七メートル、正面中央に車寄を出す。内部は中央に道場、東西に附属間を配し、北面中央に神棚を置く。格天井や鰭付懸魚等を用いた格式ある造りで大学の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009353"},{"id":"00003292","register_sub_id":"101","register_pk":"104282","name":"神戸大学本館","kana":"こうべだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.728237,"lng":135.234695,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積2041㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0117","desc":"神戸大学の前身の一つである旧神戸商業大学の本館として建てられた。ＲＣ造地上３階地下１階建で，左右対称の正面の背後に両翼を延ばす。外観はスクラッチタイル張で軒にはロンバルディア帯を廻らす。室内外とも重厚な意匠を備える昭和初期の学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003292"},{"id":"00006880","register_sub_id":"101","register_pk":"107862","name":"神戸文学館（旧関西学院ブランチ・メモリアル・チャペル）","kana":"こうべぶんがくかん（きゅうかんせいがくいんぶらんち・めもりある・ちゃぺる）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市灘区王子町3-1-2","lat":34.709103,"lng":135.213226,"geo_status":"db","era":"明治37／昭和24・平成4改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積342㎡、塔屋付","structure_material":"煉瓦造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"28 － 0303","desc":"王子公園の西南隅に建つ。当初は学院の礼拝堂兼講堂として建設、南北棟の礼拝堂とその西面北寄りに付く小集会所、南西隅の塔からなる。妻面は飾石で緩やかな尖頭アーチをつくり、その内に円窓と３連の尖頭アーチ窓を配する。明治期における教会堂の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006880"},{"id":"00014893","register_sub_id":"101","register_pk":"519153","name":"篠山小学校一号棟","kana":"ささやましょうがっこう１ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07387222,"lng":135.21905,"geo_status":"db","era":"昭和28年／昭和30年増築、平成14年・同26年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積718㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0807","desc":"篠山城跡内に位置する小学校。一号棟は木造二階建切妻造桟瓦葺。北面中央玄関と西階段から南へ渡廊下が五号棟まで延びる。玄関庇を張出し、東は南面一、二階通しの出窓、防火壁西の増築は横連窓。北側片廊下の南に教室を並べる。戦後復興期の学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014893"},{"id":"00014894","register_sub_id":"101","register_pk":"519154","name":"篠山小学校二号棟","kana":"ささやましょうがっこう２ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07364444,"lng":135.21899167,"geo_status":"db","era":"昭和30年／平成11年・同26年改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積309㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0808","desc":"一号棟の南、東西の渡廊下の間に建つ。木造二階建で切妻造桟瓦葺とする。片廊下平面の両端が階段室。一、二階に特別教室を各二室配す。南面は上下階とも横連窓で開口を大きくし、窓間と腰を横板張。北面はモルタル塗である。先に竣工した棟より簡素な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014894"},{"id":"00014895","register_sub_id":"101","register_pk":"519155","name":"篠山小学校三号棟","kana":"ささやましょうがっこう３ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07340278,"lng":135.21901944,"geo_status":"db","era":"昭和29年／平成11年・同26年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積352㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0809","desc":"二号棟の南、東西渡廊下の間に建つ木造二階建切妻造桟瓦葺。西の階段室は片廊下の北に取付く直線階段。東渡廊下上に二階が張出す。南面は横連窓で開口大きく、窓間と腰を横板張。北面は窓を一間毎に開け、モルタル塗仕上。竣工が前後する棟と少し異なる構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014895"},{"id":"00014896","register_sub_id":"101","register_pk":"519156","name":"篠山小学校四号棟","kana":"ささやましょうがっこう4ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07319444,"lng":135.21916667,"geo_status":"db","era":"昭和28年／平成10年・同26年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積546㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0810","desc":"三号棟の南、東渡廊下を越え東に延びる木造二階建切妻造桟瓦葺。北側片廊下の南に普通教室を並べ、中央東寄りに防火壁を立上げる。南面は側柱筋の外に柱を立て出窓とする構成。窓は横長窓で欄間も開け大開口を確保。窓間と腰は横板張。構成に創意ある教室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014896"},{"id":"00014897","register_sub_id":"101","register_pk":"519157","name":"篠山小学校五号棟","kana":"ささやましょうがっこう5ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07296111,"lng":135.21919722,"geo_status":"db","era":"昭和27年／昭和60年・平成26年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積520㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0811","desc":"四号棟の南、東渡廊下を越え東に延びる木造二階建切妻造桟瓦葺。北側片廊下の普通教室棟で中央東寄りに防火壁を立上げる。南面は柱を上下階に通した出窓で欄間付の横連窓、窓下は引出収納。二階階段ホールに独立円柱が立つ。創意現れた戦後復興期の学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014897"},{"id":"00014898","register_sub_id":"101","register_pk":"519158","name":"篠山小学校講堂","kana":"ささやましょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07361389,"lng":135.21935556,"geo_status":"db","era":"昭和10年／昭和中期・平成26年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄骨造平屋建、人工スレート葺、建築面積586㎡","structure_material":"鉄骨造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0812","desc":"二号棟と三号棟の東に建つ。鉄骨造平屋建南北棟、屋根は切妻造人工スレート葺。外壁は木下地のモルタル塗で、腰はスクラッチ・タイル貼。内部は北面の幅一杯に舞台を設ける。鉄製のフィンク・トラス小屋組で大空間を実現。戦前期の希少な鉄骨造の学校講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014898"},{"id":"00000745","register_sub_id":"101","register_pk":"101735","name":"三田学園創立二十五周年記念図書館","kana":"さんだがくえんそうりつにじゅうごしゅうねんきねんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三田市南ケ丘2-13-65","lat":34.87694946,"lng":135.21726583,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造３階建，瓦葺，建築面積470㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"28 － 0028","desc":"中学本館の北方の丘上に建つスパニッシュスタイルの図書館建築。玄関のある鉄筋コンクリート造平屋建部を主体とし，西に３階建塔屋付き書庫棟を配する。玄関奥左手の大棟と庇の境に３連の屋根窓をつけ，屋根及び小庇ともスペイン瓦を葺く。設計は置塩章。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000745"},{"id":"00000744","register_sub_id":"101","register_pk":"101734","name":"三田学園中学本館","kana":"さんだがくえんちゅうがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三田市南ケ丘2-13-65","lat":34.87556237,"lng":135.21732992,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造２階建，銅板葺，建築面積1062㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"28 － 0027","desc":"木造２階建，石綿スレート葺，下見板貼スティックスタイルの校舎で，中央部に玄関，両端にウィングを張りだす。玄関部頂部の櫛形ペディメントが印象的。神戸の藍原（兵二郎）建築事務所の設計で，イギリスのパブリックスクールを模したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000744"},{"id":"00002433","register_sub_id":"101","register_pk":"103423","name":"私立灘中学校・灘高等学校本館","kana":"しりつなだちゅうがっこう・なだこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区魚崎北町8-5-1","lat":34.719471,"lng":135.26825,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積497㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"28 － 0072","desc":"宗建築事務所設計の学校建築。鉄筋コンクリート造２階建で，１階を事務室，２階を講堂とする。外観は縦長窓をデザインの基調とし，１階は石積風の横目地を施し，２階正面は窓に尖りアーチ状の飾り枠をつける。学校のシンボルとして地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002433"},{"id":"00010986","register_sub_id":"101","register_pk":"208956","name":"柏陵記念館","kana":"はくりょうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市柏原町東奥字中道50","lat":35.130958,"lng":135.082398,"geo_status":"db","era":"明治30／昭和16・同35移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"28-0643","desc":"兵庫県柏原尋常中学校本館の教室及び昇降口を移築改修した擬洋風建築。木造平屋建、寄棟造桟瓦葺、外壁下見板張で背面にベランダを付す。玄関ポーチは胴張りを持つコリント式風の円柱でペディメントを支え、玄関脇の付柱上部には鳩の彫刻を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010986"},{"id":"00001336","register_sub_id":"101","register_pk":"102326","name":"姫路工業大学講堂（旧姫路高等学校講堂）","kana":"ひめじこうぎょうだいがくこうどう（きゅうひめじこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市新在家本町1-1-12","lat":34.84706428,"lng":134.68866779,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、スレート葺、建築面積450㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"28 － 0056","desc":"旧本館の右手奥に西面して建つ。木造２階建，下見板貼で，旧本館と共通するデザインでまとめられているが，トスカナ式の角柱を持つ玄関ポーチとその上部の切妻破風を両脇の角塔が挟む立面構成をとることで正面性をより強調したものとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001336"},{"id":"00001335","register_sub_id":"101","register_pk":"102325","name":"姫路工業大学ゆりの木会館（旧姫路高等学校本館）","kana":"ひめじこうぎょうだいがくゆりのきかいかん（きゅうひめじこうとうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市新在家本町1-1-12","lat":34.84738287,"lng":134.68791517,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、スレート葺、建築面積483㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"28 － 0055","desc":"木造２階建，下見板貼スティックスタイルによる文部省直轄学校建築の一事例。正面中央の破風の処理などにセセッション風の幾何学的装飾が見られる他，車寄を設けずにアーチ形の正面玄関とし，背面に通り抜けるような造りとしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001335"},{"id":"00016418","register_sub_id":"101","register_pk":"536485","name":"兵庫県立明石高等学校中部講堂","kana":"ひょうごけんりつあかしこうとうがっこうなかべこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県明石市荷山町1744","lat":34.65773056,"lng":135.00906111,"geo_status":"db","era":"昭和31年／平成27年改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造2階一部3階建、鉄板葺、建築面積1，092㎡","structure_material":"鉄骨造及び鉄筋コンクリート造2階一部3階建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0846","desc":"明石城跡の北東に位置する高校に実業家の中部謙吉が寄附した講堂。鉄骨造及び鉄筋コンクリート造２階一部３階建。桁行41メートル、梁間25メートルで、内部は鉄骨造の三弦トラスで無柱の大空間を実現する。尖頭形のヴォールト屋根が外観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016418"},{"id":"00008312","register_sub_id":"101","register_pk":"133954","name":"兵庫県立長田高等学校神撫会館（旧兵庫県立第三神戸中学校図書館）","kana":"ひょうごけんりつながたこうとうがっこうじんぶかいかん（きゅうひょうごけんりつだいさんこうべちゅうがっこうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市長田区池田谷町2-5-1","lat":34.67009084,"lng":135.14275044,"geo_status":"db","era":"大正12年／昭和29年・昭和38年・昭和55年・平成17年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積173㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0455","desc":"校地西方の小丘に建ち、建築面積１７４㎡、鉄筋コンクリート造平屋建である。左右対称の立面構成で、正面中央の玄関ポーチ上部にペディメント状の壁を立ち上げ、両翼の張り出しに太い柱型をつくり頂部に十字を飾る。設計担当の兵庫県営繕課の力量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008312"},{"id":"00005194","register_sub_id":"101","register_pk":"106184","name":"佐保会館","kana":"さほかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市北魚屋西町","lat":34.689018,"lng":135.827576,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"29 － 0094","desc":"市中心部に位置する奈良女子大学の構内北端に南面して建つ。桁行１３間，梁間６間の入母屋造，木造２階建で，正面に車寄を設ける。各階腰部を竪板張とした真壁造で，縦長上下窓を四面に配し，妻飾は豕扠首とする。たちの高い堂々とした構えの大学同窓会館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005194"},{"id":"00014505","register_sub_id":"101","register_pk":"513919","name":"天理図書館西館","kana":"てんりとしょかんにしかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県天理市杣之内町元山口方1050-13","lat":34.59466667,"lng":135.846075,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積1，326㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0336","desc":"天理図書館西館は、ロマネスクを基調とし要所にライト風を取り入れた外観意匠、書庫を中心に閲覧室や事務室などを一体化した平面配置、書棚を構成する鉄骨書架柱で四層のコンクリートスラブを支える書庫の構造等が特徴的な天理教全体の総合図書館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014505"},{"id":"00014506","register_sub_id":"101","register_pk":"513920","name":"天理図書館東館","kana":"てんりとしょかんひがしかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県天理市杣之内町元山口方1050-13","lat":34.59469444,"lng":135.84645278,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造7階建、建築面積1，211㎡","structure_material":"鉄筋コンクリート造7階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0337","desc":"天理図書館東館は天理大学の校地中央東寄りの傾斜地にあり、西館後方に建つロマネスク調の増築書庫棟。二～四階部分に六層の書庫フロアを設け、外観は下階部瘤出し仕上の凝灰岩貼、上部はスクラッチタイル貼とし、西館と一体とした外観意匠を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014506"},{"id":"00009358","register_sub_id":"101","register_pk":"194151","name":"奈良県立畝傍高等学校倉庫（旧動力室）","kana":"ならけんりつうねびこうとうがっこうそうこ（きゅうどうりょくしつ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.50921684,"lng":135.79922215,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0202","desc":"南館の北面西寄りに建ち南北に出入口を開く。木造平屋建、桁行五・五メートル梁間五・五メートル、切妻造桟瓦葺、妻入である。妻面にトラスの架構を現し、鎧板の換気窓を設けるなど洋風意匠でまとめる。昭和初期における学校の附属建物の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009358"},{"id":"00009355","register_sub_id":"101","register_pk":"194148","name":"奈良県立畝傍高等学校本館北館","kana":"ならけんりつうねびこうとうがっこうほんかんきたかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.50941314,"lng":135.79940418,"geo_status":"db","era":"昭和8年／昭和51年・平成2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、瓦葺、建築面積983㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0199","desc":"校地の南側中央に位置し、校庭に北面して建つ。鉄筋コンクリート造三階建、東西九四・七メートル南北一〇メートル、正面中央に宝形造本瓦葺の塔屋をつくり車寄を出す。陸屋根の四周は本瓦葺とする。近代的な建物の要所に和風意匠を取り入れた和洋折衷の校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009355"},{"id":"00009356","register_sub_id":"101","register_pk":"194149","name":"奈良県立畝傍高等学校本館南館","kana":"ならけんりつうねびこうとうがっこうほんかんみなみかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.5091169,"lng":135.79940775,"geo_status":"db","era":"昭和8年／昭和44年・昭和48年・平成2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積755㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0200","desc":"北館の南側に平行して建ち、渡廊下を介して北館と接続する。鉄筋コンクリート造三階建、東西七五・一メートル南北一〇メートル、背面中央に切妻造本瓦葺の塔屋をのせる。陸屋根の四周は本瓦葺とする。北館とあわせて昭和初期の学校建築の姿を良好に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009356"},{"id":"00009357","register_sub_id":"101","register_pk":"194150","name":"奈良県立畝傍高等学校本館渡廊下","kana":"ならけんりつうねびこうとうがっこうほんかんわたりろうか","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.50925253,"lng":135.79941132,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0201","desc":"北館の南面中央と南館の北面中央を接続する。鉄筋コンクリート造二屋建、南北二一・八メートル東西四・六メートル、東面に平屋建の倉庫等を附属する。パラペットには雁振瓦をのせ、和風意匠を演出する。北館、南館とあわせて工の字平面の大型校舎を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009357"},{"id":"00014199","register_sub_id":"101","register_pk":"508829","name":"旧上秋津小学校校舎（秋津野ガルテン）","kana":"きゅうかみあきづしょうがっこうこうしゃ（あきづのがるてん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県田辺市上秋津字平岡4558-8","lat":33.75601667,"lng":135.40703611,"geo_status":"db","era":"昭和28年／平成20年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積667㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"30-0319","desc":"右会津川沿い農村の長大な木造校舎。二階建切妻造桟瓦葺、外壁は下見板張、軒際漆喰仕上とする。内部は片廊下式で、二階に背面側丘上へ避難路を設け、鉄筋コンクリート界壁と防火扉、キングポスト・トラス小屋組に土壁界壁、筋交と方杖など防災を重視する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014199"},{"id":"00014665","register_sub_id":"101","register_pk":"515207","name":"旧制粉河高等女学校同窓会館（粉河高等学校同窓会館）洋館","kana":"きゅうせいこかわこうとうじょがっこうどうそうかいかん（こかわこうとうがっこうどうそうかいかん）ようかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県紀の川市粉河字植田4600","lat":34.27448889,"lng":135.40863056,"geo_status":"db","era":"昭和9年／昭和38年・同60年・令和4年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺及びスレート葺、建築面積218㎡","structure_material":"木造2階建一部平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0339","desc":"粉河市街地東の高台にある女学校の開校２０周年記念に建築した同窓会館。切妻造スペイン瓦葺の木造二階建。二階は一五畳二間続きの大広間で、三面に広縁を巡らす。赤色の急勾配大屋根で、白壁に縦長窓を連続して並べ、スパニッシュを基調とする外観が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014665"},{"id":"00014666","register_sub_id":"101","register_pk":"515208","name":"旧制粉河高等女学校同窓会館（粉河高等学校同窓会館）和館","kana":"きゅうせいこかわこうとうじょがっこうどうそうかいかん（こかわこうとうがっこうどうそうかいかん）わかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県紀の川市粉河字植田4600","lat":34.27437778,"lng":135.40888333,"geo_status":"db","era":"昭和9年／昭和60年・令和4年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0340","desc":"女学校の同窓会館として開校２０周年記念に建てた和館。宝形造スレート葺、真壁造で和風を基調とする平屋建で、同窓会館洋館東に接続。欄間を多用する明るい続き間座敷が中心の間取りで、玄関脇に洋風応接間を配する。かつては炊事等の宿泊実習に用いた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014666"},{"id":"00013620","register_sub_id":"101","register_pk":"504989","name":"旧制和歌山中学校運動場スタンド（桐蔭高等学校運動場スタンド）","kana":"きゅうせいわかやまちゅうがっこううんどうじょうすたんど（とういんこうとうがっこううんどうじょうすたんど）","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市吹上5丁目39-1他","lat":34.21888333,"lng":135.17592222,"geo_status":"db","era":"大正11年／昭和後期改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造、延長156m","structure_material":"鉄筋コンクリート造","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0290","desc":"校地東半を占める運動場の北辺から東辺に設けた観覧席である。敷地東の丘陵斜面を利用し、コンクリート製客席は北面では中央階段の西が一一段、東が一〇段、東面は一二段で中間に二箇所の階段を設ける。建設以来、同校のグラウンドを象徴する施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013620"},{"id":"00013619","register_sub_id":"101","register_pk":"504988","name":"旧制和歌山中学校図書館（桐蔭高等学校同窓会館）","kana":"きゅうせいわかやまちゅうがっこうとしょかん（とういんこうとうがっこうどうそうかいかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市吹上5丁目1-17","lat":34.2186,"lng":135.17436389,"geo_status":"db","era":"昭和4年／昭和53年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、陸屋根、建築面積125㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0289","desc":"敷地の北面中央に建つ旧図書館の閲覧室部分。鉄筋コンクリート造平屋建の陸屋根で西面玄関ポーチは太い円柱が厚みを減じた水平庇を受ける。正面壁面中央にモルタル塗で旧制中学校章を飾る。床下換気口グリルに中の字をあしらう。簡明な意匠の近代建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013619"},{"id":"00015215","register_sub_id":"101","register_pk":"530639","name":"旧羽根学園熊野高等経理学校校舎","kana":"きゅうはねがくえんくまのこうとうけいりがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県新宮市丹鶴二丁目7683-51","lat":33.728875,"lng":135.99200833,"geo_status":"db","era":"昭和12年／昭和40年増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造一部鉄骨造2階建、瓦葺一部鉄板葺、建築面積215㎡","structure_material":"木造一部鉄骨造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0376","desc":"新宮城跡の南に位置する旧経理学校校舎。通りに西面する木造２階建入母屋造桟瓦葺で玄関ポーチを付し外壁下見板張。一階は中廊下形式、二階は一室の大教室で、東半は鉄骨造の別棟増築部。玄関ポーチに四つ玉算盤の欄間を掲げ、開学時の息吹を伝える洋風校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015215"},{"id":"00016716","register_sub_id":"101","register_pk":"579200","name":"高野山高等学校講堂","kana":"こうやさんこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字谷上183-1他","lat":34.216711,"lng":135.577178,"geo_status":"db","era":"昭和11年／昭和49年改修、同53年頃移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積435㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0426","desc":"壇上伽藍の北西に位置する高校の講堂。校舎群中央部に建つ入母屋造妻入鉄板葺で外壁漆喰塗、腰は簓子下見板張。外陣は１２６畳の広大な畳敷で、格天井に玉杢の杉板を用いる。内陣は一段高い板敷とし、両脇に護摩堂、香華場を配す。当校を象徴する巨大な講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016716"},{"id":"00016717","register_sub_id":"101","register_pk":"579201","name":"高野山高等学校校門","kana":"こうやさんこうとうがっこうこうもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字谷上207","lat":34.214982,"lng":135.578156,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、間口6.8m","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0427","desc":"敷地南端に建つ正門。一対の門柱は鉄筋コンクリート造、正方形平面、高さ２・２メートル。表面は頁岩貼仕上とする。頂部に載せる灯塔は宝形造鉄板葺で段葺とし軒を反らせる。灯身は格子にガラスを嵌め、内部に電灯を入れる。極太の門柱で堂々とした姿の校門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016717"},{"id":"00001014","register_sub_id":"101","register_pk":"102004","name":"高野山大学図書館","kana":"こうやさんだいがくとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山385","lat":34.21152504,"lng":135.58593081,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上３階地下１階建，建築面積569㎡","structure_material":"鉄筋コンクリート造地上３階地下１階建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0035","desc":"３０万冊の仏教書を収蔵・公開する施設として武田五一の設計，清水組の施工により建設された。鉄筋コンクリート造地下室付３階建の質実な図書館建築で，正面中央玄関の左手を研究室，右手を閲覧室に充て，閲覧室の背後に内部５層の書庫を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001014"},{"id":"00009523","register_sub_id":"101","register_pk":"194316","name":"北海道大学和歌山研究林本館","kana":"ほっかいどうだいがくわかやまけんきゅうりんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県東牟婁郡古座川町平井560-1他","lat":33.64273293,"lng":135.68955524,"geo_status":"db","era":"昭和2年／平成7年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積182㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"30 － 0170","desc":"平井川左岸、平井集落の中に建つ演習林宿舎。Ｈ形平面の木造二階建で、両翼部の妻壁を見せた切妻造鉄板葺。外壁は下見板張で、両翼妻壁はシングル張とする。窓は二連、三連の上下窓を引違に改修。小屋組は繋梁入の垂木小屋。紀伊山中に建つ札幌農学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009523"},{"id":"00003297","register_sub_id":"101","register_pk":"104287","name":"湯浅小学校講堂","kana":"ゆあさしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡湯浅町湯浅1570","lat":34.035488,"lng":135.181366,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄骨造平屋建、瓦葺、建築面積978㎡","structure_material":"鉄骨造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"30 － 0049","desc":"鉄骨造の講堂。内部は後方に舞台と左右二室を設ける他は一室とする。正面ポーチには三連アーチを設け，左右の側面は柱型を見せた横板張に出目地を走らせ，上部は平坦なモルタル塗りとする。凹凸のリズミカルな側面と荘重な正面の対比で特徴的な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003297"},{"id":"00001524","register_sub_id":"101","register_pk":"102514","name":"大谷大学尋源館（旧本館）","kana":"おおたにだいがくじんげんかん（きゅうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区小山上総町20-1","lat":35.04185345,"lng":135.75849987,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積587㎡","structure_material":"煉瓦造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"26 － 0058","desc":"烏丸通北大路下るの現在地にキャンパスを移した際の大学本館。赤煉瓦に石でドレッシングした明治調の躯体に軽快な玄関ポーチと小塔を付ける。ゲーブルには大正期のセセッション的意匠が認められる。設計は須藤勉と山本八太郎とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001524"},{"id":"00004595","register_sub_id":"101","register_pk":"105585","name":"旧京都市立有済小学校太鼓望楼","kana":"きゅうきょうとしりつゆうさいしょうがっこうたいこぼうろう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区大和大路通三条下る東側大黒町169","lat":35.00788844,"lng":135.77363412,"geo_status":"db","era":"明治9／昭和27移築","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造2層、鉄板葺、建築面積9㎡","structure_material":"木造2層","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0195","desc":"木造２階建の有済小学校講堂の大棟中央に付設されていた。ＲＣ造校舎新築に伴い，屋上に保存された。木造で，内部は２層構成になる。宝形造の望楼部を高く立て，庇を付けた下部を袴腰風の縦板張で覆う簡素なつくりであるが，地域の人々に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004595"},{"id":"00007220","register_sub_id":"101","register_pk":"108202","name":"京都芸術センター北館（旧京都市立明倫小学校北校舎）","kana":"きょうとげいじゅつせんたーきたかん（きゅうきょうとしりつめいりんしょうがっこうきたこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.005695,"lng":135.758881,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積499㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0305","desc":"西館の北面東端と渡廊下で接続する鉄筋コンクリート造３階建。西端の南への突出部は２、３階へのスロープで、端部を四半円形につくる。南面東寄りに運動場への出入口を開く。内部は北側片廊下で教室が並び、東端は特別教室とした。３階窓上庇が水平線を強調。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007220"},{"id":"00007221","register_sub_id":"101","register_pk":"108203","name":"京都芸術センター正門及び塀（旧京都市立明倫小学校正門及び塀）","kana":"きょうとげいじゅつせんたーせいもんおよびへい（きゅうきょうとしりつめいりんしょうがっこうせいもんおよびへい）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.00544318,"lng":135.75813008,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 鉄筋コンクリート造門柱2基、間口2.9m、両側通用門付 塀 鉄筋コンクリート造、延長25m","structure_material":"門 鉄筋コンクリート造門柱2基","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0306","desc":"敷地西側の室町通に開く門。鉄筋コンクリート造の門柱は断面八角形で、各角に柱形をつけ、セセッション風の造形をみせる。頂部はドーム形である。両側に同形で一まわり小さな門柱を建て、脇門とする。塀の親柱も門柱と同意匠で、一体感のある景観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007221"},{"id":"00007218","register_sub_id":"101","register_pk":"108200","name":"京都芸術センター西館（旧京都市立明倫小学校本館）","kana":"きょうとげいじゅつせんたーにしかん（きゅうきょうとしりつめいりんしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.00542731,"lng":135.75837231,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積661㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0303","desc":"東西に長い鉄筋コンクリート造２階建。室町通に開く門から南面の切妻屋根の玄関にアプローチする。１階は西半が事務室、東半が旧体操場、２階は西半が和風の大広間、東半が旧講堂である。パラペットのスペイン瓦と、西妻２階のバルコニーが外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007218"},{"id":"00007219","register_sub_id":"101","register_pk":"108201","name":"京都芸術センター南館（旧京都市立明倫小学校南校舎）","kana":"きょうとげいじゅつせんたーみなみかん（きゅうきょうとしりつめいりんしょうがっこうみなみこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.00530362,"lng":135.7589087,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積652㎡","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0304","desc":"西館の南面東端から東へ延びる、鉄筋コンクリート造３階一部４階建。西端に半円アーチの入口を設け、北面東寄りに運動場への出入口を開く。北側片廊下で教室が並び、東端は特別教室、４階に作法室を配した。西端塔屋の寄棟屋根と３連の円形窓の意匠が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007219"},{"id":"00006972","register_sub_id":"101","register_pk":"107954","name":"京都工芸繊維大学（旧京都高等工藝學校）自動車庫","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）じどうしゃこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.0493391,"lng":135.78229031,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積30㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0271","desc":"本館の北東方、現中央西門の南の敷地外周沿いに南面して建つ。鉄筋コンクリート造平屋建、陸屋根造、スクラッチタイル貼で、平面規模は正面５．１ｍ奥行５．５ｍとし、東面及び西面北端に張出しを設ける。水平線を強調した庇や各部軒の意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006972"},{"id":"00006973","register_sub_id":"101","register_pk":"107955","name":"京都工芸繊維大学（旧京都高等工藝學校）正門及び門衛所","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）せいもんおよびもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.048374,"lng":135.782211,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 コンクリート造門柱2基、間口5.4m、左右通用門付 門衛所 鉄筋コンクリート造平屋建、建築面積30㎡","structure_material":"門 コンクリート造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0272","desc":"本館の南東方、構内敷地の東南隅部に位置する。正門は鉄筋コンクリート造石貼で、東に脇門、西の門衛所寄りに通用門を開く。門衛所は、鉄筋コンクリート造平屋建、陸屋根造、スクラッチタイル貼で、五角形平面とし、西側に台所、便所等を備えた宿直室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006973"},{"id":"00006971","register_sub_id":"101","register_pk":"107953","name":"京都工芸繊維大学（旧京都高等工藝學校）倉庫","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）そうこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.04836528,"lng":135.78152262,"geo_status":"db","era":"昭和6／昭和39移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積80㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0270","desc":"本館南翼の南方に北面して建つ。鉄筋コンクリート造２階建、陸屋根造、スクラッチタイル貼で、規模は正面１０ｍ奥行８．０ｍとし、北東隅部に階段を配し、屋上に塔屋を上げる。北面と南面には柱形を現し、壁面頂部にコーニスをまわす。窓には内側に鉄扉を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006971"},{"id":"00006970","register_sub_id":"101","register_pk":"107952","name":"京都工芸繊維大学（旧京都高等工藝學校）本館及び講堂","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）ほんかんおよびこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.048817,"lng":135.78186,"geo_status":"db","era":"昭和5／平成15改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2251㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0269","desc":"京都高等工藝學校教授本野精吾の設計に基づく。鉄筋コンクリート造３階建、スクラッチタイル貼で、平面は背面に両翼を伸ばし、正面玄関の奥に講堂部を突き出したＥ字形とする。北面及び南面の２、３階を薄く張出し連続窓としたモダニズム色の強い意匠に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006970"},{"id":"00007224","register_sub_id":"101","register_pk":"108206","name":"京都国際マンガミュージアム旧北校舎棟（旧京都市立龍池小学校北校舎）","kana":"きょうとこくさいまんがみゅーじあむきゅうきたこうしゃとう（きゅうきょうとしりつたついけしょうがっこうきたこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.011951,"lng":135.759232,"geo_status":"db","era":"昭和12／平成18改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積415㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0309","desc":"敷地の北辺、旧講堂棟の東に位置する鉄筋コンクリート造３階建。西端と中央東寄りに階段室があり、もとは北側片廊下であったが、１、２階は一部の間仕切を撤去している。外壁の各柱間には縦長の方形窓を３つずつ配し、垂直性を強調した外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007224"},{"id":"00007223","register_sub_id":"101","register_pk":"108205","name":"京都国際マンガミュージアム旧講堂棟（旧京都市立龍池小学校講堂）","kana":"きょうとこくさいまんがみゅーじあむきゅうきゅうこうどうとう（きゅうきょうとしりつたついけしょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.011871,"lng":135.758957,"geo_status":"db","era":"昭和3／平成18改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積507㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0308","desc":"旧本館棟の北に連続する鉄筋コンクリート造２階建。西面南寄りに片持ちの庇をつけた入口を開く。内部は１階を体操場、２階を講堂とした。１階はアーチ窓、２階は縦長の方形窓を開き、窓間に突出したアール・デコ意匠の方立と柱形で、リズム感のある外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007223"},{"id":"00007225","register_sub_id":"101","register_pk":"108207","name":"京都国際マンガミュージアム旧正門及び塀（旧京都市立龍池小学校正門及び塀）","kana":"きょうとこくさいまんがみゅーじあむきゅうせいもんおよびへい（きゅうきょうとしりつたついけしょうがっこうせいもんおよびへい）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.01157783,"lng":135.75885555,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"門 石造門柱2基、間口4.7m 塀 鉄筋コンクリート造、延長53m","structure_material":"門 石造門柱2基","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0310","desc":"敷地西側の両替町通に開く門。単純な正方形断面の石造の門柱である。門両側の塀は腰高の連続壁で、上端を笠石形とし、その上に角柱を建てて金属柵を付ける。旧講堂棟出入口の両脇には通用門が開く。要所に段状繰形を施し、簡素ながら繊細な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007225"},{"id":"00007222","register_sub_id":"101","register_pk":"108204","name":"京都国際マンガミュージアム旧本館棟（旧京都市立龍池小学校本館）","kana":"きょうとこくさいまんがみゅーじあむきゅうほんかんとう（きゅうきょうとしりつたついけしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.011559,"lng":135.758972,"geo_status":"db","era":"昭和4／平成18改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積669㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0307","desc":"敷地西側の両替町通に面して建つ鉄筋コンクリート造２階建。正面中央に玄関を開き、南・北に翼棟をつけたＨ形平面をもつ。玄関は片持ちの庇を付け、上部の窓は額縁と方立はアール・デコ風の意匠。西面窓の方立で垂直性を強調し、簡潔で特色ある外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007222"},{"id":"00004597","register_sub_id":"101","register_pk":"105587","name":"京都市学校歴史博物館（旧京都市立開智小学校）石塀","kana":"きょうとしがっこうれきしはくぶつかん（きゅうきょうとしりつかいちしょうがっこう）いしべい","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区御幸町通仏光寺下る橘町437","lat":35.00053082,"lng":135.76623294,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造、延長56m","structure_material":"石造","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0197","desc":"大正期の敷地拡張時に建設された。正門南北に延び，門廻りの隅は円形に築く。京都白川石を用いた重厚な間知石布積で，通り側は丁寧な瘤出仕上げとする。頂部には笠石を置き，現在は土盛に芝を張っている。往時の有様を伝えるとともに，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004597"},{"id":"00004596","register_sub_id":"101","register_pk":"105586","name":"京都市学校歴史博物館（旧京都市立開智小学校）正門","kana":"きょうとしがっこうれきしはくぶつかん（きゅうきょうとしりつかいちしょうがっこう）せいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区御幸町通仏光寺下る橘町437","lat":35.00076614,"lng":135.766227,"geo_status":"db","era":"明治34／大正7移築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造、瓦葺、間口3.5m、両側袖塀付","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0196","desc":"御幸町通に東面して建つ。間口３．５ｍの背面に控柱を立てた高麗門形式で，屋根は切妻造，本瓦葺になる。南北に袖塀をつけ，南には潜戸を設ける。親柱は高く延ばして棟木を支え，桁は前後とも腕木で受ける。明治期における学校建築の形式の一端を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004596"},{"id":"00006644","register_sub_id":"101","register_pk":"107627","name":"京都市学校歴史博物館玄関（旧成徳小学校玄関車寄）","kana":"きょうとしがっこうれきしはくぶつかんげんかん（きゅうせいとくしょうがっこうげんかんくるまよせ）","category":"学校","subcategory":"その他工作物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区麩屋町通仏光寺下る鍋屋町248-2","lat":35.000854,"lng":135.765762,"geo_status":"db","era":"明治8／明治42・平成18移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造、瓦葺、面積8.1㎡","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"26 － 0268","desc":"明治２年開校の「下京第九番組小学校」（移転時に成徳小学校と改称）の校舎の玄関車寄。間口４．０ｍ規模で、正面に起りをつけた切妻破風を見せる。トスカナ式のオーダーを模した素木の柱がほほえましい。擬洋風になる番組小学校校舎の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006644"},{"id":"00001921","register_sub_id":"101","register_pk":"102911","name":"京都大学総合人間学部正門（旧第三高等学校正門）","kana":"きょうとだいがくそうごうにんげんがくぶせいもん（きゅうだいさんこうとうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田二本松町","lat":35.02516183,"lng":135.7804451,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、間口3.3m、左右通用門及び袖壁付","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0070","desc":"京大構内南部吉田二本松地区に位置する。木造門柱の両脇に，通用門が付く。大門柱の礎石部と木製柱身部が追掛大栓継ぎで結合される点に特徴があり，門扉は上桟をアーチ状とし，全体で和洋が混在したデザインとする。門衛所と共に真水英夫の設計と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001921"},{"id":"00001922","register_sub_id":"101","register_pk":"102912","name":"京都大学総合人間学部門衛所（旧第三高等学校門番所）","kana":"きょうとだいがくそうごうにんげんがくぶもんえいじょ（きゅうだいさんこうとうがっこうもんばんしょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田二本松町","lat":35.02510024,"lng":135.78034121,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0071","desc":"三高吉田学舎が京都帝国大学に譲渡されるに伴い，新三高キャンパスの門衛所として正門と同時に建設。木造，鉄板葺，ドイツ下見の平屋建。東面の受付部を八角屋根状に造り，居室部の切妻屋根と組み合わせる。二本松学舎における明治期建造物の数少ない遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001922"},{"id":"00000740","register_sub_id":"101","register_pk":"101730","name":"京都大学尊攘堂","kana":"きょうとだいがくそんじょうどう","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田本町","lat":35.02679647,"lng":135.77904892,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造平屋建，瓦葺，建築面積172㎡","structure_material":"煉瓦造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0021","desc":"品川弥次郎が創設した記念堂に由来する。品川の死後、関係資料と建設資金が京大に寄付され、京大構内に新築された。煉瓦造スタッコ塗りで鉄造の玄関ポーチを有し，開口部など平明な意匠で仕上げられており，小堂ながら構内では異色の建築になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000740"},{"id":"00000741","register_sub_id":"101","register_pk":"101731","name":"京都大学農学部演習林事務室","kana":"きょうとだいがくのうがくぶえんしゅうりんじむしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区北白川追分町","lat":35.03118827,"lng":135.78542664,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積438㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0022","desc":"大倉三郎の設計。スパニッシュ瓦葺，ベランダをめぐらしたバンガロー風の木造建築で，ベランダ天井の意匠などモダニズムの清新さ溢れる作品に仕上がっている。京大北部構内の独特の農村的景観形成にも大きく寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000741"},{"id":"00000595","register_sub_id":"101","register_pk":"101585","name":"京都大学農学部表門及び門衛所","kana":"きょうとだいがくのうがくぶおもてもんおよびもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区北白川追分町","lat":35.02974921,"lng":135.78548307,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"26 － 0017","desc":"分離派建築会に参加した森田慶一の秀作で，通用口の尖頭アーチなど楽友会館と共通するディテールが認められる。ドイツ表現派のモチーフを採りながら，日本瓦を載せた薄い屋根が頂部を明確に水平に区切って節度を与え，全体意匠を品格あるものに仕立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000595"},{"id":"00001920","register_sub_id":"101","register_pk":"102910","name":"京都大学本部構内正門（旧第三高等中学校正門）","kana":"きょうとだいがくほんぶこうないせいもん（きゅうだいさんこうとうちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田本町","lat":35.02539028,"lng":135.78089186,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"石造、間口3.3m、片側通用門及び左右袖壁付","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0069","desc":"京都大学キャンパスの中枢をなす本部の正門。当キャンパス内で最初期の建造物で，第三高等中学校正門として建設。門柱は石面と擬石面を交互に重ね，背面に大きな控えをとる。門柱の左右に石造袖塀を付け，西側に通用口を開ける。設計は山口半六と久留正道。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001920"},{"id":"00013584","register_sub_id":"101","register_pk":"504947","name":"光華女子学園旧正門及び石垣","kana":"こうかじょしがくえんきゅうせいもんおよびいしがき","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区西京極野田町39","lat":34.995225,"lng":135.71915833,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"旧正門 鉄筋コンクリート造門柱、間口4.0m、両側脇門柱付 石垣 石造、総延長88m","structure_material":"旧正門 鉄筋コンクリート造門柱","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0612","desc":"西京極に位置する。東本願寺の大谷智子が開学した女子学園の正門。間口四メートルで石張の門柱両脇に脇門を構える。門柱の笠石は直方体の内部を刳り抜く独特な意匠。左右に伸びる石垣は延長八八メートルで表側は切石布積とし、上部を生垣として景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013584"},{"id":"00013585","register_sub_id":"101","register_pk":"504948","name":"光華女子学園旧通用門及び石垣","kana":"こうかじょしがくえんきゅうつうようもんおよびいしがき","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区西京極野田町39","lat":34.99521944,"lng":135.71809722,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"旧通用門 石造門柱、間口2.6m、脇門柱付、石垣 石造、総延長20m","structure_material":"旧通用門 石造門柱","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0613","desc":"通用門は間口二・六メートルの石造門柱の西脇に脇門がつくが、脇門はコンクリートで閉塞されている。両脇に伸びる石垣の延長は二〇メートルで正門石垣同様上部を生垣とする。正門石垣とともに学校敷地周囲の景観を形成し、歴史ある女子学園のよすがを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013585"},{"id":"00010835","register_sub_id":"101","register_pk":"201670","name":"紫明会館","kana":"しめいかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区小山南大野町1-3他","lat":35.039643,"lng":135.756289,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積335㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0491","desc":"京都府師範学校の同窓会館として、紫明通に面して建てられた鉄筋コンクリート造三階建。外壁はスタッコ塗でアーチ窓を並べ、パラペット頂部をスペイン瓦葺、内外の細部をアール・デコ風意匠で飾る。講堂や和室を有するなど社会教育目的の建築的特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010835"},{"id":"00004991","register_sub_id":"101","register_pk":"105981","name":"同志社アーモスト館","kana":"どうししゃあーもすとかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入相国寺門前町632","lat":35.03010835,"lng":135.76255728,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、スレート葺、建築面積343㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0200","desc":"構内ほぼ中央で西面して建つ。桁行２２ｍ，梁間１２ｍのＲＣ造３階建，平入で，南面にサンルームを張出し，大型の腰折れ屋根には煙突や屋根窓を左右対称に配す。外装煉瓦張で，隅部では竜山石を算木積状に張るなど，材料を丁寧に使い分け華やかさを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004991"},{"id":"00006539","register_sub_id":"101","register_pk":"107522","name":"同志社啓明館西館","kana":"どうししゃけいめいかんにしかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.029812,"lng":135.762497,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦及び鉄筋コンクリート造4階建、スレート葺、建築面積153㎡、渡廊下付","structure_material":"煉瓦及び鉄筋コンクリート造4階建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0257","desc":"図書館書庫として建設。煉瓦造及びＲＣ造４階建で，切妻屋根をスレート葺とする。本館から延びる煉瓦造２階建の渡廊下が接続する。両側面には２階以上を一連に扱ったアーチ形窓を反復し，外観意匠の主題としている。両妻の壁面にも大きなアーチを描いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006539"},{"id":"00006538","register_sub_id":"101","register_pk":"107521","name":"同志社啓明館本館","kana":"どうししゃけいめいかんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.029629,"lng":135.762573,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦及び鉄筋コンクリート造5階建、スレート葺、建築面積406㎡","structure_material":"煉瓦及び鉄筋コンクリート造5階建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0256","desc":"図書館本館として，書庫である西館の南に建設された。煉瓦造及びＲＣ造５階建で，スレート葺の切妻屋根とし，南西隅の塔は入口ホールと階段室とする。外壁にバットレスを現し，アーチ形窓枠はタイルで装飾する。入口上部の重厚なアーチ形庇など洗練された意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006538"},{"id":"00001919","register_sub_id":"101","register_pk":"102909","name":"同志社女子大学栄光館","kana":"どうししゃじょしだいがくえいこうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.029728,"lng":135.764267,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上2階一部3階地下1階建、瓦葺、建築面積1637㎡、塔屋付","structure_material":"鉄筋コンクリート造地上2階一部3階地下1階建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0068","desc":"ジェームズ館と静和館（現存せず）間に建造。ＲＣ造２階一部３階建。煉瓦造の前述２館との景観的統一性に配慮し煉瓦タイル張とする。中央玄関上の庇とテラス高欄に浅彫を施し，その上部に大規模な八角塔屋を冠す。玄関と背面に突出する講堂の内部意匠は秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001919"},{"id":"00001918","register_sub_id":"101","register_pk":"102908","name":"同志社女子大学ジェームズ館","kana":"どうししゃじょしだいがくじぇーむずかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.02962096,"lng":135.76364518,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造地上2階地下1階建、瓦葺、建築面積697㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0067","desc":"明治末期に始まるキャンパス内校舎改築時に，Ｗ・ジェームズ夫人の寄付により建設。煉瓦造２階建，桟瓦葺で正面玄関に歯飾をあしらった櫛形ペディメントを構える。カルフォルニアの民家建築を参考にしたと伝わる。栄光館と同じく武田五一の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001918"},{"id":"00001334","register_sub_id":"101","register_pk":"102324","name":"福知山市立惇明小学校本館","kana":"ふくちやましりつじゅんめいしょうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府福知山市字内記21","lat":35.29658973,"lng":135.124832,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造・鉄骨造2階建、鉄板葺、建築面積755㎡","structure_material":"木造・鉄骨造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0050","desc":"木造を主体としつつ梁・小屋組に鉄骨を用いた２階建の学校建築。装飾要素は少なく，特に正面入口横と２階隅部の大小の丸窓と連続窓にモダニズム建築の影響が見られ，２階全体を占める講堂は光に溢れる空間となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001334"},{"id":"00006142","register_sub_id":"101","register_pk":"107126","name":"平安女学院昭和館","kana":"へいあんじょがくいんしょうわかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区室町通下立売下る武衛陣町220","lat":35.01976,"lng":135.758087,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階一部3階建、建築面積975㎡、半地階付","structure_material":"鉄骨鉄筋コンクリート造2階一部3階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0242","desc":"敷地北西隅に建ち。間口１８ｍ，奥行５５ｍの規模で，鉄骨鉄筋コンクリート造２階一部３階建とする。半地下部分に講堂，１階に職員室，２階に教室，３階にピアノ室を設ける。外壁を１階モルタル塗，２階煉瓦タイル貼とする。昭和初期のＳＲＣ造の学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006142"},{"id":"00004140","register_sub_id":"101","register_pk":"105130","name":"平安女学院明治館","kana":"へいあんじょがくいんめいじかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区下立売通室町東入五町目町178-2","lat":35.01952676,"lng":135.75875555,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積370㎡","structure_material":"煉瓦造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0166","desc":"平安女学院の現在地への移転に際して建てられた校舎建築。煉瓦造の南北棟，桟瓦葺，切妻造３棟を並べ，妻面はダッチ・ゲイブルを持ち特色ある外観をつくる。設計はＡ・Ｎ・ハンセル。我国におけるクイーン・アン・リバイバル様式の最初期の事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004140"},{"id":"00004816","register_sub_id":"101","register_pk":"105806","name":"智頭町立山形小学校校舎","kana":"ちづちょうりつやまがたしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字郷原238","lat":35.26405949,"lng":134.27601016,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積1061㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"31 － 0091","desc":"町中心部から東方を流れる北股川の右岸に位置する。桁行８１ｍ，梁間１０ｍの長大な木造２階建で，鉄板葺，平入，外装下見板張とする。簡素ながら，西面全長にわたり窓を連続させるなど，水平性を強調したデザインが特徴的。山間部に良好に残る近代木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004816"},{"id":"00000085","register_sub_id":"101","register_pk":"101075","name":"いなさ会館（旧島根県立第三中学校講堂）","kana":"いなさかいかん（きゅうしまねけんりつだいさんちゅうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市大社町北荒木1473","lat":35.38145165,"lng":132.70312718,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積324㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"32 － 0004","desc":"旧制中学校の講堂として建てられ，開口部の上げ下げ窓や下見板張りとする外観は，擬洋風様式でまとめあげる。昭和５５年に現在地に移築されたが，同時に解体された旧校舎の玄関ポーチが組み込まれ，思い出の校舎として一体的に保存活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000085"},{"id":"00000548","register_sub_id":"101","register_pk":"101538","name":"旧田所小学校講堂","kana":"きゅうたどころしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県邑智郡邑南町大字下亀谷210","lat":34.85028054,"lng":132.51950408,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積395㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"32 － 0010","desc":"入母屋の大屋根を架す典型的な小学校講堂建築。側面出入口の腰折れ型の庇，妻面開口部枠の扁平アーチ，妻飾りなどに大正昭和期木造建築の特徴が示されている。瑞穂町教育の歴史を物語る施設として，卒業生のみならず多くの町民から親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000548"},{"id":"00016603","register_sub_id":"101","register_pk":"574965","name":"旧吉田村尋常高等小学校講堂（吉田町生涯学習交流館）","kana":"きゅうよしだむらじんじょうこうとうしょうがっこうこうどう（よしだちょうしょうがいがくしゅうこうりゅうかん）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県雲南市吉田町吉田1082-8","lat":35.28778861,"lng":132.90037778,"geo_status":"db","era":"昭和12年／平成6年移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積475㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"32 - 0222","desc":"市街地中心部に位置する旧小学校講堂。平屋建切妻造妻入桟瓦葺で北に半切妻造玄関を張出す。外壁下見板張で腰は竪板張とし両側面に控壁を設ける。内部はトラスを用いた無柱の大空間で天井を折上げ、飾縁で軽快にみせる。旧小学校の歴史を伝えるモダンな講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016603"},{"id":"00006090","register_sub_id":"101","register_pk":"107075","name":"島根大学旧奥谷宿舎（旧制松江高等学校外国人宿舎）","kana":"しまねだいがくきゅうおくだにしゅくしゃ（きゅうせいまつえこうとうがっこうがいこくじんしゅくしゃ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県松江市奥谷町140","lat":35.481041,"lng":133.053772,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"32 － 0046","desc":"松江城よりほぼ７００ｍ北方に位置する。正面９ｍ，奥行１４ｍ規模，南側を半切妻とした木造２階建で，正面２階の張り出し部分を玄関ポーチの柱で支える。１階下見板張，２階モルタル塗仕上げとし，２連及び３連の連続窓を四周に配する瀟洒な住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006090"},{"id":"00006092","register_sub_id":"101","register_pk":"107077","name":"島根大学正門（旧制松江高等学校正門）","kana":"しまねだいがくせいもん（きゅうせいまつえこうとうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市西川津町1060","lat":35.484669,"lng":133.06813,"geo_status":"db","era":"大正13／昭和45移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"石造門柱4基、間口16m","structure_material":"石造門柱4基","registered":"2007.05.15(平成19.05.15)","register_no":"32 － 0047","desc":"市街地東北部に位置する島根大学の正門で，南面して構える。方１．２ｍ，高さ２．１ｍ規模の門柱を間口１６ｍで配し，両脇には高さ１．７ｍの袖柱を添え，いずれも花崗岩で築く。頂部を十字形平面で象り，全体にセセッション風のデザインをあしらうのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006092"},{"id":"00006010","register_sub_id":"101","register_pk":"106995","name":"赤磐市吉井郷土資料館（旧仁堀尋常高等小学校本館）","kana":"あかいわしよしいきょうどしりょうかん（きゅうにぼりじんじょうこうとうしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県赤磐市周匝136","lat":34.91838288,"lng":134.09180807,"geo_status":"db","era":"昭和2／昭和59移築改造","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積199㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0153","desc":"市東北部の旧吉井町役場に隣接して建つ。桁行２２ｍ，梁間９．１ｍ規模，寄棟造，平入の木造２階建。外壁を下見板張とドイツ壁で仕上げ，正面中央に懸魚付の駒形破風と玄関ポーチ，端部には表現主義的意匠の通用口を設けるスティックスタイルの校舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006010"},{"id":"00008567","register_sub_id":"101","register_pk":"134963","name":"岡山県立岡山朝日高等学校（旧第六高等学校）柔道場","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）じゅうどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市中区古京町2-1241-1","lat":34.66028747,"lng":133.94550434,"geo_status":"db","era":"大正8年／昭和63年・平成19年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0235","desc":"校地の東寄りに建ち、桁行一八メートル梁間一三メートル、木造平屋建、切妻造妻入鉄板葺である。煉瓦基礎に建ち、外壁は簓子下見板張で、当初から方杖で支持する。小屋は洋小屋とし、床組にバネを装置して弾力をもたせる。大正期の柔道場の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008567"},{"id":"00008570","register_sub_id":"101","register_pk":"134966","name":"岡山県立岡山朝日高等学校（旧第六高等学校）正門及び石積","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）せいもんおよびいしづみ","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市中区古京町2-80-2他","lat":34.66113924,"lng":133.94265448,"geo_status":"db","era":"明治33年／昭和前期・平成元年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"正門 石造、間口4.1m、両側通用門付 石積 石造、延長1032m","structure_material":"正門 石造","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0238","desc":"校地西辺の正門と、校地を囲う石積である。正門は矩形の石柱を四本たて、中央間四・二メートル脇間一・五メートルとし、各間に木扉を開く。石積は総延長一、〇三二メートル高さ一・五メートル、割石の谷積と布積とする。伝統校に相応しい風格を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008570"},{"id":"00008569","register_sub_id":"101","register_pk":"134965","name":"岡山県立岡山朝日高等学校（旧第六高等学校）西書庫","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）にししょこ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県岡山市中区古京町2-200-2","lat":34.66146583,"lng":133.94363947,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積82㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0237","desc":"校地北辺に東書庫と並び建つ。東西八・七メートル南北九・六メートル、鉄筋コンクリート造三階建、陸屋根である。煉瓦造の基礎のほか、各階に付したコーニスや矩形の連続窓など、東書庫の外観と調和が図られ、東書庫とともに旧制第六高等学校の伝統を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008569"},{"id":"00008568","register_sub_id":"101","register_pk":"134964","name":"岡山県立岡山朝日高等学校（旧第六高等学校）東書庫","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）ひがししょこ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市中区古京町2-200-2","lat":34.66145046,"lng":133.94374194,"geo_status":"db","era":"明治35年／昭和前期・昭和中期・昭和60年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造3階建、瓦葺、建築面積68㎡","structure_material":"煉瓦造3階建","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0236","desc":"校地北辺に西書庫と並び建つ。桁行九・三メートル梁間七・四メートル、煉瓦造三階建、切妻造桟瓦葺である。煉瓦基礎に建ち、小屋は洋小屋を組む。外壁はモルタル塗で、各階にコーニスを三筋付け、均等に配した窓に鉄格子をはめる。堅牢なつくりの書庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008568"},{"id":"00006410","register_sub_id":"101","register_pk":"107393","name":"岡山県立倉敷天城高等学校武道場（旧岡山県天城中学校武道場）","kana":"おかやまけんりつくらしきあまきこうとうがっこうぶどうじょう（きゅうおかやまけんあまきちゅうがっこうぶどうじょう）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県倉敷市藤戸町天城269","lat":34.56395137,"lng":133.8111891,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0160","desc":"校地中央に建つ木造平屋建。桁行１５間、梁間６間の入母屋造桟瓦葺。東正面の切妻造玄関とその上部の千鳥破風を豕叉首で飾る。外壁は真壁造白漆喰塗で、腰を竪板張とする。内部は南北に分けて柔道場と剣道場とする。造作も丁寧な武道場の標準的事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006410"},{"id":"00006409","register_sub_id":"101","register_pk":"107392","name":"岡山県立高松農業高等学校資料館（旧岡山県立農学校堆肥舎）","kana":"おかやまけんりつたかまつのうぎょうこうとうがっこうしりょうかん（きゅうおかやまけんりつのうがっこうたいひしゃ）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松原古才336-2","lat":34.68310625,"lng":133.82058806,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造平屋建、茅葺、建築面積99㎡","structure_material":"煉瓦造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0159","desc":"校地の南寄り中央に建つ煉瓦造平屋建である。桁行１１ｍ、梁間９．１ｍの南北棟で、トラス小屋の入母屋造茅葺とする。煉瓦外壁はフランス積で、各面２箇所にバットレスをつけ、壁上部を漆喰塗とする。虫籠窓風高窓は後の改造。煉瓦造に茅葺屋根の特異な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006409"},{"id":"00006039","register_sub_id":"101","register_pk":"107024","name":"岡山大学医学部正門（旧岡山医科大学正門）","kana":"おかやまだいがくいがくぶせいもん（きゅうおかやまいかだいがくせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区鹿田町2-5-1","lat":34.65252462,"lng":133.91983642,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造門柱4基、間口10m","structure_material":"煉瓦造門柱4基","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0152","desc":"岡山大学鹿田キャンパスの正門で，照明を含め高さ３．６ｍ，門口６．２ｍで配された門柱と，両脇の高さ２．６ｍの袖柱からなる。いずれも基礎に花崗岩を用い，柱身を赤煉瓦の小口積とし，柱頭部にセセッション風のデザインをあしらう華やかなつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006039"},{"id":"00006038","register_sub_id":"101","register_pk":"107023","name":"岡山大学医学部門衛所（旧岡山医科大学門衛所）","kana":"おかやまだいがくいがくぶもんえいじょ（きゅうおかやまいかだいがくもんえいじょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区鹿田町2-5-1","lat":34.65252909,"lng":133.91970166,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0151","desc":"市街地の南方に位置する岡山大学鹿田キャンパスの正門脇に建つ。桁行６．４ｍ，梁間３．６ｍ規模の寄棟造，平屋建で，外壁は下見板張，腰縦板張，玄関廻りには上下窓を配する。変形六角平面の屋根で，鱗形の天然スレートを葺く特徴ある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006038"},{"id":"00012638","register_sub_id":"101","register_pk":"367932","name":"旧赤坂尋常高等小学校校舎","kana":"きゅうあかさかじんじょうこうとうしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県赤磐市馬屋字上山1434-7","lat":34.735298,"lng":133.993317,"geo_status":"geocoded","era":"明治43年／昭和48年移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積268㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0303","desc":"久米南町から移築した、もと赤坂尋常高等小学校の校舎。寄棟造二階建で、左手に平屋棟を附属する。正面玄関のアーチ状装飾や小壁の襷状意匠、屋根上に円形窓を載せる外観、独特な形式をもつトラスの小屋組等の特徴が、県技師・江川三郎八の関与を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012638"},{"id":"00001941","register_sub_id":"101","register_pk":"102931","name":"倉敷市歴史民俗資料館（旧倉敷幼稚園園舎）","kana":"くらしきしれきしみんぞくしりょうかん（きゅうくらしきようちえんえんしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市西中新田655","lat":34.58470021,"lng":133.77397907,"geo_status":"db","era":"大正4／昭和56移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"33 － 0051","desc":"倉敷幼稚園園舎として造られ現在市役所東側に建つ，木造平屋建の洋風建築。東西に延びる正面棟の背面に，天井が放射状に分割された八角棟が接続。屋根構成が変化に富む。外壁真壁漆喰塗，腰縦及び横板張とし，玄関上部の切妻破風に桜花文様レリーフを掲げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001941"},{"id":"00010235","register_sub_id":"101","register_pk":"198068","name":"金光学園中学高等学校記念講堂","kana":"こんこうがくえんちゅうがくこうとうがっこうきねんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県浅口市金光町占見新田1350-6","lat":34.545169,"lng":133.62491,"geo_status":"db","era":"明治37／昭和31移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"33 － 0266","desc":"校地南辺に建ち、寄棟造の屋根に半円形屋根窓を設ける。外壁は下見板張で腰を竪板張、小壁は漆喰塗とし、軒を雲形持送で飾る。内部柱は柱頭に円弧形方杖を付ける。天井は二重折上格天井で、灯具釣元は三重に折上げる。和洋の意匠を巧みに融和させた明治期の学舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010235"},{"id":"00002311","register_sub_id":"101","register_pk":"103301","name":"閑谷学校資料館","kana":"しずたにがっこうしりょうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県備前市閑谷740","lat":34.796993,"lng":134.21817,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積762㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"33 － 0054","desc":"私立閑谷中学校本館として建設。寄棟造，桟瓦葺の木造２階建校舎で，両翼を南前方に張り出したコの字型平面をとり，北側に廊下，その両端に階段を配する。外観は木骨を表に現したスティックスタイルをとる。設計は，遷喬小学校と同じ岡山県工師の江川三郎八。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002311"},{"id":"00006130","register_sub_id":"101","register_pk":"107114","name":"ノートルダム清心女子大学ノートルダムホール東棟","kana":"のーとるだむせいしんじょしだいがくのーとるだむほーるひがしとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区伊福町2-16-9","lat":34.672749,"lng":133.91713,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2176㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0155","desc":"本館の東に位置し，東面するＲＣ造３階建。正面は色ガラスの入った小窓を整然と並べ，鐘楼には丸柱を配す等，幾何学的なデザイン要素がふんだんに採り入れられている。礼拝堂の天井は緩やかなアーチを描く。室内の照明器具はオリジナル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006130"},{"id":"00006129","register_sub_id":"101","register_pk":"107113","name":"ノートルダム清心女子大学ノートルダムホール本館","kana":"のーとるだむせいしんじょしだいがくのーとるだむほーるほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区伊福町2-16-9","lat":34.67250824,"lng":133.91627842,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積3250㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0154","desc":"敷地南に配置され南面する。南東角に正面玄関が設けられている。ＲＣ造２階建で，中庭を囲むロの字型の平面計画。外観は，連続する庇により水平線を強調し，柱と連続する窓枠は規律的なデザインである。昭和初期のモダニズム建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006129"},{"id":"00003470","register_sub_id":"101","register_pk":"104460","name":"小野公民館（旧小野尋常小学校校舎）","kana":"おのこうみんかん（きゅうおのじんじょうしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県神石郡神石高原町大字小野900-2","lat":34.83411197,"lng":133.31080468,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積761㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"34 － 0042","desc":"昭和４年建築の木造小学校校舎。平屋建で，東西に長い長方形平面を持つ。北側に２.１ｍ幅の廊下を通し，南側に教室を配する。中央に玄関を開くとともに，西端に児童昇降所を設ける。木造校舎は県内でも数少なく，昭和初期学校建築の有様を伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003470"},{"id":"00008571","register_sub_id":"101","register_pk":"134967","name":"旧大草尋常高等小学校奉安殿","kana":"きゅうおおぐさじんじょうこうとうしょうがっこうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市大和町大草9068-1","lat":34.50016852,"lng":132.95728535,"geo_status":"db","era":"昭和11年／昭和44年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造平屋建、建築面積2.9㎡、基壇付","structure_material":"石造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0104","desc":"小学校庭隅の石積基壇上に建ち、間口一・七メートル奥行一・七メートル、石造である。切石布積の躯体前面にたつドリス式風の円柱で庇を受ける。隅反りのある屋根石上に宝珠状の頂石を載せ、四方に切妻の小屋根を置く。独特な形式になる石造奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008571"},{"id":"00000707","register_sub_id":"101","register_pk":"101697","name":"広島大学附属中・高等学校講堂（旧制広島高等学校講堂）","kana":"ひろしまだいがくふぞくちゅう・こうとうがっこうこうどう（きゅうせいひろしまこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県広島市南区翠1-1-1","lat":34.3719472,"lng":132.46552774,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積507㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"34 － 0016","desc":"旧制広島高等学校の講堂として昭和２年に建築されたもので，正面に車寄が付く。外壁は石造風に仕上げ，１・２階通しの柱型付きとし軒先に装飾タイルを貼る。全体として様式建築を簡素にまとめた意匠構成となるが，仕事は丁寧で技術的に見るべき点は多い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000707"},{"id":"00002439","register_sub_id":"101","register_pk":"103429","name":"福山誠之館高等学校記念館","kana":"ふくやませいしかんこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市木之庄町6-822-1","lat":34.502331,"lng":133.360901,"geo_status":"db","era":"安政1／昭和8増築／昭和44移築","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"34 － 0036","desc":"福山誠之館は安政元年に創設された福山藩校である。昭和８年に当初の学堂の玄関部分と新築の主屋を組み合わせ，記念館として開館した。近世の雄大な唐破風玄関と近代の入母屋造の主屋が巧みに融合した構成で，和風の意匠と造形の連続性をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002439"},{"id":"00008579","register_sub_id":"101","register_pk":"134975","name":"普光寺観音堂（旧大田尋常高等小学校奉安殿）","kana":"ふこうじかんのんどう（きゅうおおたじんじょうこうとうしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県世羅郡世羅町大字井折288","lat":34.59491481,"lng":133.04132549,"geo_status":"db","era":"昭和10年／昭和21年移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造平屋建、建築面積3.3㎡、基壇付","structure_material":"石造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0112","desc":"境内南寄りの山門西側に築いた亀甲石積の基壇上に建ち、間口、奥行とも一・八メートル、石造である。切石布積の躯体前面にたてたドリス式風の円柱で庇を受ける。屋根は三段構成で、下段は下端を蛇腹状につくり、上段は切妻形で、妻面に蔓状の紋様を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008579"}];
